INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('4a47218d-21b0-4831-aec5-6f3022eab4b9', 'studio_world_locations', '0ec6d614-226a-4edf-ac49-e1e2dcd302b3', 'Sunken Dominion / Abyssal Reach', 'f887a689-ad83-436b-9425-1d19fa24086f', 'renitaparker@me.com', '{"id":"0ec6d614-226a-4edf-ac49-e1e2dcd302b3","name":"Sunken Dominion / Abyssal Reach","tags":["imported-draft"],"map_x":50,"map_y":50,"user_id":"db618e68-0656-4b9b-b308-81e071faf745","image_url":null,"is_public":false,"created_at":"2026-09-25T04:47:58.369286+00:00","updated_at":"2026-09-25T04:47:58.369286+00:00","archived_at":null,"description":"Imported from a character profile. Review and classify this draft location.","canon_status":"concept","location_type":"other","spoiler_level":"private","codex_record_id":null,"workflow_status":"draft","parent_location_id":null}', '2026-09-25 06:15:31.18293+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('0ebd9e63-2901-44d5-92d1-2bc8f33edbe0', 'studio_world_locations', '9e789fe1-a93c-46f5-994c-32d984c7cb28', 'Sunken Dominion', 'f887a689-ad83-436b-9425-1d19fa24086f', 'renitaparker@me.com', '{"id":"9e789fe1-a93c-46f5-994c-32d984c7cb28","name":"Sunken Dominion","tags":["imported-draft"],"map_x":50,"map_y":50,"user_id":"db618e68-0656-4b9b-b308-81e071faf745","image_url":null,"is_public":false,"created_at":"2026-09-25T05:04:21.574766+00:00","updated_at":"2026-09-25T05:04:21.574766+00:00","archived_at":null,"description":"Imported from a character profile. Review and classify this draft location.","canon_status":"concept","location_type":"other","spoiler_level":"private","codex_record_id":null,"workflow_status":"draft","parent_location_id":null}', '2026-09-25 06:15:37.27483+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('c68e9e71-d8d1-4b56-87fb-545ea32bab09', 'studio_characters', '7538e2ae-03cd-4c2f-a116-05e51b4fa245', 'Ruchika', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"7538e2ae-03cd-4c2f-a116-05e51b4fa245","name":"Ruchika","media":{"tbdFields":"Exact age\nBirth date\nExact birthplace\nExact weight\nDominant hand\nName meaning\nNationality\nRomantic partner\nPermanent enemies","canonLocks":"Ruchika is the Bone Dragon\nMale\nSon of Terrax and Leviathans\nEarth + Water heritage\nBrother of Gaius\nBrother of Ife\nBrother of Rahim\nLives in the Shifting Sands with Gaius\nRuchika is a wanderer\nRuchika is a master craftsman\nRuchika crafted Ife''s Bone Dragon Whip\nRuchika is not missing\nRuchika does not have memory loss\nTrue form uses an ivory bone exoskeleton\nDragon wings have water-like membranes","galleryUrl":"","mediaNotes":"Human and dragon references should preserve the same ivory, midnight blue, slate gray, earth brown, black, and golden amber palette.","galleryUrls":[],"portraitUrl":"","visualAssets":"Official character portrait — Needed\nFull-body front view — Needed\nBack view — Needed\nLeft view — Needed\nRight view — Needed\nFace reference — Needed\nHair reference — Needed\nOutfit breakdown — Needed\nBone weapon reference — Needed\nTrue Bone Dragon Form — Needed\nCombat reference — Needed\nBone Dragon Whip — Done","productionNotes":"Keep his silhouette tall and grounded. Bone should be modeled separately from skin and clothing so it can emerge, retract, break, and regenerate during animation.","referenceArtUrl":"","alternateFormUrl":""},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"TBD","era":"500–1300 AD-inspired fantasy era","name":"Ruchika","race":"Dragon","alias":"The Bone Dragon","gender":"Male","titles":"The Bone Dragon\nThe Ivory Artisan\nThe Wandering Craftsman","subrace":"Elemental Dragon","summary":"Ruchika is the Bone Dragon, born from Earth and Water. He is a disciplined craftsman, powerful defender, and natural wanderer who lives in the Shifting Sands with his brother Gaius.","heritage":"Indian + Asian","homeland":"Shifting Sands","pronouns":"He/Him","birthDate":"TBD","nicknames":"Ruchi","occupation":"Master Craftsman and Wanderer","affiliation":"Terrax and Leviathans bloodline","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"Major","pronunciation":"Roo-chee-kah","currentResidence":"Shifting Sands","elementalHeritage":"Earth + Water"},"abilities":{"weapons":"Manifested bone blades\nBone spears\nBone shields\nBone gauntlets","strengths":"Extreme durability\nPowerful defense\nRapid regeneration\nVersatile weapon creation\nExcellent battlefield control\nHigh physical strength\nSkilled craftsmanship","weaknesses":"Large constructs require more energy\nRepeated regeneration causes fatigue\nExtreme damage can slow reconstruction\nProtective instincts can be exploited","combatStyle":["Defensive combat","Counterattacking","Close-range combat","Battlefield control","Adaptive weapon creation"],"limitations":["Bone creation consumes energy","Density increases require concentration","Large-scale regeneration is exhausting","Cannot endlessly create massive structures"],"powerSource":["Bone Magic","Earth lineage","Water lineage","Draconic power"],"abilityNotes":"His bone is a living synthesis of Earth minerals and Water-driven regeneration. Broken constructs can pull themselves back together when enough of his magic remains.\n\nRuchika is not missing and does not suffer from memory loss. Those story elements belong to Rahim.","combatProfile":"Ruchika fights like a moving fortress. He absorbs pressure, controls space with bone structures, and changes his weapons according to the opponent.","weaponDetails":"Ruchika normally creates weapons directly from living bone. He can alter their shape, weight, flexibility, and density during combat.","transformations":"True Bone Dragon Form\nPartial Bone Armor","primaryAbilities":"Skeletal Replication\nBone Generation\nBone Manipulation\nDensity Manipulation\nInstant Bone Mending\nBone Weapon Creation\nBone Armor Creation","secondaryAbilities":"Enhanced durability\nEnhanced strength\nStructural awareness\nMineral sensing\nRapid bone regeneration\nHeat-resistant bone constructs","signatureTechniques":"Ivory Fortress\nSkeletal Bloom\nMarrow Forge\nBone Bastion\nIvory Lance\nLiving Arsenal","transformationDetails":"In his true form, Ruchika becomes a massive dragon covered in an ivory exoskeleton. Dark slate-blue skin shows beneath the armor, while translucent water-like membranes stretch between enormous bone wing digits."},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Broad-shouldered","Athletic"],"nails":[{"hex":"#C89B83","name":"Natural"}],"eyeHex":[{"hex":"#D89B32","name":"Golden Amber"}],"height":"Approximately 6''3\" / 190 cm","makeup":"","weight":"TBD","hairHex":[{"hex":"#151218","name":"Black"}],"skinHex":[{"hex":"#9A6548","name":"Warm Medium Brown"}],"eyeColor":["Golden amber"],"grooming":"Clean and practical","skinTone":["Warm medium-brown"],"wardrobe":"Travel outfit\nCrafting outfit\nCombat outfit\nCeremonial attire","hairColor":["Black"],"hairStyle":"Long layered hair worn loose","accessories":"Living bone bracers\nCrafting tools\nTravel satchel\nUtility belt","faceDetails":["Defined jawline","High cheekbones","Straight nose","Calm expression","Thick dark eyebrows"],"hairTexture":["Thick","Slightly wavy"],"colorPalette":"Ivory — #E8DFC8\nMidnight Blue — #182A3D\nSlate Gray — #4E5963\nEarth Brown — #654A3A\nGolden Amber — #D89B32\nBlack — #151218","dominantHand":"TBD","outfitColors":"Angrakha — Midnight Blue #182A3D\nDhoti — Charcoal #292A2D\nSash — Earth Brown #654A3A\nBone Bracers — Ivory #E8DFC8\nTrim — Muted Gold #B88A3D","alternateForm":["True Bone Dragon Form"],"clothingStyle":"Early-medieval Indian-inspired clothing with practical layered construction and bone accents.","appearanceNotes":"His design combines grounded Earth elements with subtle Water influence. Bone should always appear smooth, pale ivory, and organically grown rather than metallic.","outfitMaterials":["Woven cotton","Linen","Leather","Living bone"],"postureMovement":["Upright posture","Controlled movement","Heavy grounded stance","Quiet footsteps"],"signatureOutfit":"Dark layered angrakha with a wrapped dhoti, waist sash, living bone bracers, leather sandals, and practical crafting gear.","distinguishingFeatures":["Golden amber eyes","Long black hair","Living ivory bone","Bone can emerge from his body","Natural bone bracers"]},"created_at":"2026-09-25T05:08:38.036685+00:00","updated_at":"2026-09-25T05:08:38.036685+00:00","is_complete":false,"origin_lore":{"fears":["Failing to protect family","Losing control of his creations","Seeing his work used irresponsibly"],"goals":["Perfect Bone craftsmanship","Discover rare materials","Protect Ife","Continue wandering","Preserve useful knowledge"],"beliefs":["Strength should have purpose","Creation is as important as destruction","Nothing strong is built carelessly","Freedom and responsibility can coexist"],"culture":["Terrax elemental traditions","Leviathans aquatic traditions","Shifting Sands culture","Wandering artisan traditions"],"lineage":"Son of Terrax and Leviathans","storyArc":"Ruchika begins as a self-contained wanderer focused on craft and family. His travels gradually pull him into wider conflicts where his ability to create and protect becomes increasingly important.","backstory":"Born from Earth and Water, Ruchika developed Bone as his unique elemental expression. Rather than pursuing destruction, he became a craftsman who uses his power to build, repair, protect, and create. He eventually made his home in the Shifting Sands with his brother Gaius, but his wandering nature keeps him traveling throughout the Umbral World.","childhood":"Ruchika grew up between two ancient elemental bloodlines. Terrax shaped his patience and structural thinking, while Leviathans influenced the adaptive and regenerative nature of his magic.","lifestyle":["Lives in the Shifting Sands","Frequently travels","Crafts weapons and tools","Studies natural materials","Explores ruins and distant lands"],"storyRole":"A wandering Bone Dragon and master craftsman based in the Shifting Sands. His travels allow him to appear across many regions of the Umbral World.","birthplace":"TBD","psychology":["Values stability","Shows love through actions","Needs personal freedom","Protective of family","Finds peace through craftsmanship"],"motivations":["Protect his family","Master his craft","Explore the Umbral World","Understand unusual materials","Create objects that endure"],"personality":["Calm","Disciplined","Patient","Protective","Observant","Independent","Reserved","Reliable"],"voiceSpeech":["Low calm voice","Measured speech","Rarely raises his voice","Prefers direct statements"],"likesDislikes":["Likes craftsmanship","Likes quiet places","Likes traveling","Likes durable materials","Likes learning new techniques","Dislikes waste","Dislikes reckless destruction","Dislikes unnecessary conflict"],"majorLifeEvents":"Born to Terrax and Leviathans\nAwakened Bone Dragon magic\nBecame a master craftsman\nSettled in the Shifting Sands with Gaius\nCrafted the Bone Dragon Whip for Ife\nBecame a frequent wanderer"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"Gaius\nIfe\nTerrax\nLeviathans","rivals":"","enemies":"","mentors":"Terrax — Earth and structural discipline\nLeviathans — Fluidity and regeneration","parents":"Terrax — Father\nLeviathans — Mother","partner":"","children":"","siblings":"Gaius — Brother\nIfe — Sister\nRahim — Brother","worldConnections":"Shifting Sands — Home\nTerrax — Paternal connection\nSunken Dominion — Maternal connection\nUmbral World — Wandering territory","relationshipNotes":"Ruchika lives in the Shifting Sands with Gaius and shares a strong brotherly bond with him. He is especially protective of Ife and personally crafted the Bone Dragon Whip for her. Rahim''s disappearance remains a concern for the family."},"spoiler_level":"private","race_record_id":null,"realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":null}', '2026-09-25 06:26:16.928077+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('39beb0f4-69ac-4630-9412-6ed1bff03380', 'studio_characters', '56793a81-e4e6-48b9-a18a-28f6783ead66', 'Ignis', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"56793a81-e4e6-48b9-a18a-28f6783ead66","name":"Ignis","media":{"tbdFields":"Birth date\nApparent human age\nWeight\nDominant hand\nNationality\nBirthplace\nExact origin of primordial existence\nNamed signature techniques\nPersonal weapons\nSpecific weaknesses\nSpecific power limitations\nCurrent romantic status","canonLocks":"Ignis is male\nIgnis uses he/him pronouns\nIgnis is the primordial embodiment of Fire\nIgnis is not merely a dragon ruling fire\nIgnis rules Ignis Peaks\nIgnis resides in Moltenmaw Caverns\nHuman form is approximately 7 ft tall\nHuman skin is deep mahogany brown\nEyes are luminous winter grey\nHair is long black locs with fire-like tips\nIgnis has a neat goatee\nDragon form is predominantly black\nDragon scale seams glow dark crimson\nDragon scales appear to leak magma\nDragon eyes resemble the sun\nRahim is his eldest son\nRahim is the Blood Dragon\nIfe is his daughter\nIfe is the Steam Dragon\nEzra is his son\nEzra is the Lightning Dragon\nAshóNodia is his son\nAshóNodia is the Ash Dragon\nLeviathans is the mother of Rahim and Ife\nAetheros is the mother of Ezra\nHecate is the mother of AshóNodia\nRahim is missing","galleryUrl":"","mediaNotes":"Maintain strict visual continuity with the completed Ignis portrait, dragon design, and production sheet. Future images should use the same anime/fantasy character identity rather than redesigning him.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nExpression Sheet — Done\nCombat Reference — Needed","productionNotes":"Use the established production sheet as Ignis''s primary visual canon reference. Human and dragon artwork must preserve his established proportions, palette, facial identity, hair, and primordial aesthetic. His dragon form must remain an immense obsidian-black dragon with dark-crimson glowing scale seams, magma leakage, and sun-like eyes.","referenceArtUrl":"","alternateFormUrl":""},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Ancient","era":"Primordial Era","name":"Ignis","race":"Primordial","alias":"","gender":"Male","titles":"Primordial of Fire\nThe Living Flame\nThe First Burning\nThe Sovereign Pyre\nThe Fire Dragon","subrace":"Primordial Dragon","summary":"Ignis is the primordial living embodiment of Fire and sovereign of Ignis Peaks. His dragon form is the physical manifestation of his primordial nature rather than the source of his authority. Ancient, knowledgeable, noble, cocky, and intensely competitive, Ignis is fascinated by strength and constantly seeks opponents capable of giving him exhilarating battles. He fiercely protects his realm and people while encouraging strength through challenge.","heritage":"Primordial","homeland":"Ignis Peaks","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Sovereign of Ignis Peaks","affiliation":"Ignis Peaks","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"Fire","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"IG-nis","currentResidence":"Moltenmaw Caverns, Ignis Peaks","elementalHeritage":"Primordial Fire"},"abilities":{"weapons":"","strengths":"Primordial power\nExtreme physical strength\nAncient combat experience\nFire mastery\nExceptional durability\nBattle intelligence\nDraconic power","weaknesses":"TBD","combatStyle":["Aggressive escalation","Close-quarters combat","Draconic combat","Power contests","Adaptive combat","High-output elemental combat"],"limitations":["TBD"],"powerSource":["Primordial Fire","Living embodiment of Fire"],"abilityNotes":"Ignis''s elemental authority originates from his primordial identity. Fire is not simply a learned magical discipline for him. His knowledge and combat experience are ancient, although his competitive personality often causes others to overlook his intelligence.\n\nIgnis must never be described merely as a dragon who controls fire. He is the primordial living embodiment of Fire; the Fire Dragon is one manifestation of that nature.","combatProfile":"Ignis fights because he genuinely enjoys testing strength. Against weaker opponents he may remain relaxed or deliberately limit himself. A powerful opponent causes him to progressively escalate, seeking the moment both combatants are forced to reveal everything they possess. He does not spare his children during their agreed combat competitions simply because they are family; their ability to challenge him is a source of pride.","weaponDetails":"TBD","transformations":"Primordial Fire Dragon Form","primaryAbilities":"Primordial fire manipulation\nFire generation\nHeat manipulation\nMagma manipulation\nDragon transformation\nPrimordial physical strength","secondaryAbilities":"Extreme fire resistance\nExtreme heat resistance\nDraconic flight\nPrimordial durability\nEnhanced senses","signatureTechniques":"TBD","transformationDetails":"Ignis transforms into an immense black dragon whose obsidian scales contain dim dark-crimson light between their seams. Molten magma appears to leak between portions of his scales, making his body resemble a living volcanic formation. His eyes burn with sun-like intensity. This form must remain predominantly black rather than becoming a conventional red fire dragon."},"is_public":false,"appearance":{"build":["Tall","Muscular","Powerful"],"nails":"","eyeHex":["#C9D1D4"],"height":"7 ft","makeup":"","weight":"TBD","hairHex":["#090909","#E94B16"],"skinHex":["#5A2F24"],"eyeColor":["Luminous winter grey"],"grooming":"Immaculately maintained goatee and locs","skinTone":["Deep rich mahogany brown"],"wardrobe":"Regal battle attire\nPrimordial ceremonial attire","hairColor":["Black","Fire-colored tips"],"hairStyle":"Long black locs with flame-like tips","accessories":"Gold jewelry\nDraconic ornamentation","faceDetails":["Strong masculine features","Defined jawline","Serious expression"],"hairTexture":["Locs"],"colorPalette":"Obsidian black\nDark crimson\nMolten orange\nEmber red\nAntique gold","dominantHand":"TBD","outfitColors":"Obsidian black\nDark crimson\nMolten orange\nAntique gold","alternateForm":["Primordial Fire Dragon"],"clothingStyle":"Ancient fantasy warrior nobility with volcanic and draconic motifs appropriate to the 500–1300 AD-inspired Umbra World aesthetic.","appearanceNotes":"Ignis must consistently appear as a towering Black man with deep mahogany skin, luminous winter-grey eyes, long black locs with fire-like tips, a neat goatee, and a powerful muscular build. His expression is usually serious or mildly disinterested because of his nonchalant personality. His visual presence should communicate restrained primordial power rather than constant aggression.","outfitMaterials":["Dark leather","Heavy woven fabric","Metal ornamentation"],"postureMovement":["Relaxed confidence","Commanding stance","Unhurried movement"],"signatureOutfit":"Regal black fantasy attire suited to an ancient warrior-sovereign, accented with dark crimson, molten-fire details, and restrained gold ornamentation. The silhouette is imposing without appearing overly ceremonial.","distinguishingFeatures":["Luminous winter-grey eyes","Flame-tipped locs","Very neat goatee","Towering height"]},"created_at":"2026-09-25T06:33:51.978753+00:00","updated_at":"2026-09-25T06:33:51.978753+00:00","is_complete":false,"origin_lore":{"fears":["TBD"],"goals":["Remain worthy of his strength","Protect his primordial domain","Challenge powerful beings","Battle Rahim again"],"beliefs":["Strength must be tested","Defeat can create growth","Power should be proven","Challenges reveal character","Strength deserves respect"],"culture":["Ignis Peaks","Primordial culture","Warrior culture"],"lineage":"Primordial living embodiment of Fire","storyArc":"A major emotional thread surrounding Ignis is Rahim''s disappearance. Rahim was not merely his eldest son but one of the few beings capable of providing the kind of prolonged, exhilarating battle Ignis craves. Ignis continues challenging his children and other powerful beings, but the possibility of fighting Rahim again remains uniquely important to him.","backstory":"Ignis is an ancient primordial whose existence is intrinsically connected to Fire itself. He rules Ignis Peaks from Moltenmaw Caverns and protects the civilizations that exist within his primordial domain. His fascination with strength shaped both his rule and his relationship with his children. His battles with his eldest son Rahim were among the most exhilarating fights of his existence, making Rahim''s disappearance a deeply significant absence.","childhood":"TBD","lifestyle":["Rules from Moltenmaw Caverns","Hosts combat competitions","Trains through battle","Challenges his children","Protects Ignis Peaks"],"storyRole":"Ignis functions as the primordial embodiment of Fire, sovereign protector of Ignis Peaks, and father of several powerful elemental dragons. His overwhelming power contrasts with his casual personality and love of competition. His relationship with his children reveals both his warrior philosophy and his capacity for familial pride.","birthplace":"TBD","psychology":["Craves worthy competition","Thrives on escalation","Respects earned strength","Enjoys being challenged","Misses battling Rahim","Hides wisdom beneath bravado"],"motivations":["Experience worthy battles","Protect Ignis Peaks","Test his strength","Strengthen his children","Find exhilarating opponents"],"personality":["Nonchalant","Cocky","Competitive","Battle-loving","Noble","Knowledgeable","Protective","Self-assured","Playful in combat","Strength-driven"],"voiceSpeech":["Deep voice","Calm delivery","Understated trash talk","Short challenges","Rarely raises his voice"],"likesDislikes":["Likes powerful opponents","Likes difficult battles","Likes competition","Likes courageous challengers","Likes testing new techniques","Dislikes false strength","Dislikes cowardice","Dislikes unearned arrogance"],"majorLifeEvents":"Became sovereign of Ignis Peaks\nFathered Rahim with Leviathans\nFathered Ife with Leviathans\nFathered Ezra with Aetheros\nFathered AshóNodia with Hecate\nFrequently battled Rahim\nRahim disappeared\nContinued family combat competitions"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"Rahim — Son and treasured combat rival","enemies":"","mentors":"","parents":"","partner":"TBD","children":"Rahim — Eldest son; Blood Dragon\nIfe — Daughter; Steam Dragon\nEzra — Son; Lightning Dragon\nAshóNodia — Son; Ash Dragon","siblings":"","worldConnections":"Ignis Peaks — Primordial domain\nMoltenmaw Caverns — Primary residence\nLeviathans — Mother of Rahim and Ife\nAetheros — Mother of Ezra\nHecate — Mother of AshóNodia\nCinderkin Elves — Protected people\nOrcs — Protected people\nGoblins — Protected people\nDragonborn — Protected people\nLizardfolk — Protected people\nFireborn — Protected beings","relationshipNotes":"Ignis expresses much of his affection through competition, training, and combat. Rahim, his eldest son with Leviathans, became an especially important combat partner because their battles could reach extraordinary levels of power. Ife also shares much of Ignis''s temperament and resides with him. Ezra primarily resides with his mother Aetheros but maintains a connection to his father''s domain. AshóNodia is Ignis''s son with Hecate and embodies Ash rather than conventional fire."},"spoiler_level":"private","race_record_id":null,"realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":null}', '2026-09-25 06:40:32.160295+00');
