INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('522f40cb-17bb-4c2b-9cb0-c198206e3969', 'studio_characters', 'eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478', 'Venny''Claire', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478","name":"Venny''Claire","media":{"tbdFields":"","canonLocks":"Rich warm brown skin\nDeep brown eyes\nBlack 4c hair\nWild untamed hairstyle\nCompact agile build\nNatural linen dress\nBraided leather waist cord\nLayered jewelry\nLeather sandals\nBlack werepanther form\nSilver right hind leg patch","galleryUrl":"","mediaNotes":"Official visual references include the solo human portrait, human production sheet, and black werepanther production sheet.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Maintain the established anime design across future artwork. Human-form references establish her youthful face, warm brown skin, deep brown eyes, wild 4c hair, compact build, linen dress, layered jewelry, braided leather waist cord, and sandals. Werebeast references establish the sleek black werepanther design.","referenceArtUrl":"","alternateFormUrl":""},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Venny''Claire","race":"Werebeast","alias":"","gender":"Female","titles":"","subrace":"Werepanther","summary":"Venny''Claire is one of King Kaelo''s children and the mirror counterpart of Venny''Macon. Playful, carefree, and highly curious, she embraces movement and instinct with natural confidence. Her exceptional awareness and agility make her a swift, perceptive presence who treats the world around her as something to explore.","heritage":"Dire Wolf lineage","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Exceptional agility\nHigh speed\nHeightened awareness\nFast reflexes\nFluid movement\nAcrobatic mobility","weaknesses":"","combatStyle":["Agile","Acrobatic","Instinctive","Evasive","Speed-focused"],"limitations":"","powerSource":["Werepanther heritage","Dire Wolf lineage"],"abilityNotes":"Her heightened senses provide a constant low-level stream of sensory information that guides her movements and gives her exceptional awareness of her surroundings.","combatProfile":"Venny''Claire relies on speed, agility, instinct, and constant sensory awareness rather than overwhelming physical force. Her compact werepanther form allows rapid directional changes, fluid evasive movement, and acrobatic attacks.","weaponDetails":"","transformations":"Sudo Form\nBlack Werepanther Form","primaryAbilities":"Werepanther Transformation\nEnhanced Agility\nEnhanced Speed\nHeightened Senses","secondaryAbilities":"Enhanced Awareness\nEnhanced Reflexes\nAcrobatic Movement\nStealth","signatureTechniques":"","transformationDetails":"Venny''Claire''s full werebeast form is a sleek black werepanther with a deep, inky coat that seems to absorb light. Her smaller, compact body is built for speed, stealth, and acrobatic agility. Her only visible dire wolf trait is a silver patch of fur on her right hind leg. She moves with fluid grace and retains her playful curiosity and exceptional awareness."},"is_public":false,"appearance":{"build":["Compact","Lean","Agile"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Deep brown"],"grooming":"Natural","skinTone":["Rich warm brown"],"wardrobe":"Sleeveless linen dress\nLeather sandals","hairColor":["Black"],"hairStyle":"Wild and untamed","accessories":"Braided leather waist cord\nLayered necklaces\nBeaded jewelry\nGold earrings\nGold bracelet","faceDetails":["High cheekbones","Small symmetrical nose","Youthful features"],"hairTexture":["4c","Dense"],"colorPalette":"Warm Brown\nBlack\nNatural Linen\nLeather Brown\nGold\nSilver","dominantHand":"","outfitColors":"Natural linen\nLeather brown\nGold","alternateForm":["Black Werepanther","Sudo Form"],"clothingStyle":"Light, practical clothing that allows unrestricted movement and suits the climate of Moonwood Vail.","appearanceNotes":"Venny''Claire closely mirrors Venny''Macon in facial structure, complexion, eyes, and hair. She is smaller and more compact than her brother, with a lighter frame suited to speed, agility, and acrobatic movement.","outfitMaterials":["Woven linen","Leather","Beads","Metal"],"postureMovement":["Relaxed posture","Fluid movement","Light-footed"],"signatureOutfit":"Simple sleeveless woven linen dress secured with a braided leather waist cord and worn with leather sandals.","distinguishingFeatures":["Large wide-set eyes"]},"created_at":"2026-09-25T17:42:10.890987+00:00","updated_at":"2026-09-25T18:13:05.23204+00:00","is_complete":false,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"Dire Wolf and Werepanther","storyArc":"","backstory":"","childhood":"","lifestyle":"","storyRole":"Venny''Claire represents instinct, curiosity, and freedom of movement. Her natural confidence and heightened awareness contrast with Venny''Macon''s uncertainty, making the twins mirrors in appearance but opposites in how they approach their abilities.","birthplace":"","psychology":["Highly instinctive","Constantly aware","Lives in the moment"],"motivations":["Exploration","Curiosity"],"personality":["Playful","Carefree","Curious","Unserious","Mischievous","Observant"],"voiceSpeech":"","likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nHuxleigh\nPeregrine\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Venny''Claire and Venny''Macon are mirror counterparts in appearance and temperament. Their shared features emphasize their connection, while her playful confidence and instinctive nature contrast with his reserved uncertainty."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"bbe46246-e94b-498d-9ab5-cae88e0804f7","faction_record_id":null}', '2026-09-25 18:13:37.010421+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('fafaf659-fa40-4b85-abab-654333098889', 'studio_characters', 'e229597e-305b-42fe-b232-1f78f3ac5735', 'Venny''Macon', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"e229597e-305b-42fe-b232-1f78f3ac5735","name":"Venny''Macon","media":{"tbdFields":"","canonLocks":"Rich warm brown skin\nDeep brown eyes\nBlack 4c hair\nWild untamed hairstyle\nSturdy muscular build\nNatural linen tunic\nBraided leather waist cord\nLeather sandals\nWhite werepanther form\nSilver left shoulder patch","galleryUrl":"","mediaNotes":"Official visual references include the solo human portrait, human production sheet, and white werepanther production sheet.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Maintain the established anime design across future artwork. Human-form references establish his youthful face, warm brown skin, deep brown eyes, wild 4c hair, sturdy build, linen tunic, braided leather waist cord, and sandals. Werebeast references establish the large ghost-white werepanther design.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Venny''Macon","race":"Werebeast","alias":"","gender":"Male","titles":"","subrace":"Werepanther","summary":"Venny''Macon is one of King Kaelo''s children and the mirror counterpart of Venny''Claire. Quiet and reserved, he possesses immense strength that he has yet to fully understand or embrace. His uncertainty contrasts with the tremendous potential sleeping within him.","heritage":"Dire Wolf lineage","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Immense physical strength\nHigh durability\nPowerful build\nHeightened senses","weaknesses":"Lack of confidence\nUnrefined power\nOccasional clumsiness","combatStyle":["Strength-based","Instinctive","Power-focused"],"limitations":["Untapped potential","Reluctance to use full strength"],"powerSource":["Werepanther heritage","Dire Wolf lineage"],"abilityNotes":"His greatest limitation is not a lack of power but his uncertainty about using it. Much of his strength remains dormant or restrained.","combatProfile":"Venny''Macon possesses tremendous physical potential but has not fully learned to control or trust it. His werepanther form favors raw strength, durability, and powerful movement rather than refined technique.","weaponDetails":"","transformations":"Sudo Form\nWhite Werepanther Form","primaryAbilities":"Werepanther Transformation\nEnhanced Strength\nEnhanced Durability","secondaryAbilities":"Enhanced Senses\nEnhanced Speed\nEnhanced Agility","signatureTechniques":"","transformationDetails":"Venny''Macon''s full werebeast form is a magnificent white werepanther with a ghostly white, subtly shimmering coat. He becomes substantially larger and more muscular than a typical panther. His only visible dire wolf trait is a silver patch of fur on his left shoulder. Despite his noble and powerful appearance, his movements can be slightly clumsy and his demeanor remains timid and uncertain."},"is_public":false,"appearance":{"build":["Sturdy","Muscular","Broad-shouldered"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Deep brown"],"grooming":"Natural","skinTone":["Rich warm brown"],"wardrobe":"Knee-length tunic\nLeather sandals","hairColor":["Black"],"hairStyle":"Wild and untamed","accessories":"Braided leather waist cord","faceDetails":["High cheekbones","Small symmetrical nose","Youthful features"],"hairTexture":["4c","Dense"],"colorPalette":"Warm Brown\nBlack\nNatural Linen\nLeather Brown\nGhost White\nSilver","dominantHand":"","outfitColors":"Natural linen\nLeather brown","alternateForm":["White Werepanther","Sudo Form"],"clothingStyle":"Simple, practical clothing suited to the climate and active life of Moonwood Vail.","appearanceNotes":"Venny''Macon closely mirrors Venny''Claire in facial structure, complexion, eyes, and hair. He is slightly taller and sturdier than his sister, with greater visible muscular development.","outfitMaterials":["Woven linen","Leather"],"postureMovement":["Reserved posture","Powerful movement"],"signatureOutfit":"Simple knee-length woven linen tunic secured with a braided leather cord and worn with leather sandals.","distinguishingFeatures":["Large wide-set eyes"]},"created_at":"2026-09-25T17:41:56.33402+00:00","updated_at":"2026-09-25T17:41:56.33402+00:00","is_complete":true,"origin_lore":{"fears":["His own potential"],"goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"Dire Wolf and Werepanther","storyArc":"His arc follows the gradual awakening of his immense potential and his struggle to gain confidence in his own strength.","backstory":"","childhood":"","lifestyle":"","storyRole":"Venny''Macon embodies the sleeping giant: immense natural power restrained by uncertainty and reluctance. His development centers on learning to understand and accept the strength already within him.","birthplace":"","psychology":["Unsure of his potential","Reluctant to embrace his power"],"motivations":"","personality":["Quiet","Reserved","Timid","Uncertain","Kind-hearted"],"voiceSpeech":"","likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nHuxleigh\nPeregrine\nVenny''Claire","worldConnections":"Moonwood Vail","relationshipNotes":"Venny''Macon and Venny''Claire are mirror counterparts in appearance and temperament. Their shared features emphasize their connection, while his reserved uncertainty contrasts with her playful confidence."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"bbe46246-e94b-498d-9ab5-cae88e0804f7","faction_record_id":null}', '2026-09-25 18:15:37.584711+00');
