INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('28ee718c-f007-40ac-92d2-5a4d8ff243da', 'studio_characters', '60e6b4b0-fa5e-46ed-b202-7d8cea244f87', 'Gemma', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"60e6b4b0-fa5e-46ed-b202-7d8cea244f87","name":"Gemma","media":{"tbdFields":"Mother''s name\nHuman eye color\nHuman height\nHuman weight\nDominant hand","canonLocks":"Deep rich ebony skin\n4C braided hair\nBone-rimmed spectacles\nCowrie shells\nWooden hair beads\nNatural linen clothing\nWere-gorilla transformation\nMidnight-black werebeast fur\nGolden-brown werebeast mane\nAmber werebeast eyes\nCrimson spiritual markings\nGolden tail-tuft\nAfrican drums\nGōurīrā Loa connection","galleryUrl":"","mediaNotes":"Existing visual references establish Gemma''s anime-inspired human appearance, were-gorilla form, and full gorilla mode.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/60e6b4b0-fa5e-46ed-b202-7d8cea244f87/portrait/1790364214194-gemma-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nWere-Gorilla Form — Done\nFull Gorilla Mode — Done","productionNotes":"Maintain a high-detail anime fantasy aesthetic. Her human design should emphasize her scholarly, spiritual presence, while her were-gorilla design should balance formidable physical power with feminine, playful expressiveness.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/60e6b4b0-fa5e-46ed-b202-7d8cea244f87/reference/1790364310030-gemma-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/60e6b4b0-fa5e-46ed-b202-7d8cea244f87/alternate/1790364230710-gemma-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Mid 20s","era":"500–1300 AD-inspired","name":"Gemma","race":"Werebeast","alias":"","gender":"Female","titles":"Princess of the Monkey Clan","subrace":"Were-Gorilla","summary":"Gemma is a princess of Moonwood Vail and the spiritual intermediary among King Kaelo''s children. A devoted scholar of Voodoo and the Loa, she combines ancestral spirituality, ritual drumming, and immense were-gorilla strength. She is destined to become the chosen human vessel of Gōurīrā Loa, the trickster spirit of the Monkey King.","heritage":"","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"Princess","affiliation":"Monkey Clan","apparentAge":"Mid 20s","canonStatus":"Canon","nameMeaning":"","nationality":"Moonwoodvail","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"African Drums","strengths":"Immense physical strength\nSpiritual versatility\nPowerful grappling\nAncestral assistance\nSensory deception\nHigh agility","weaknesses":"","combatStyle":["Spirit Brawler","Close-quarters combat","Grappling","Spiritual misdirection"],"limitations":"","powerSource":["Werebeast physiology","Ancestral spirits","Loa","Gōurīrā Loa"],"abilityNotes":"Gōurīrā Loa is the trickster spirit of the Monkey King and Gemma''s destined Loa. Their union grants wild, liberating chaos energy capable of shifting reality, manipulating perception through sensory illusions, and reinforcing Gemma''s physical attacks with spiritual force.","combatProfile":"Gemma combines the physical strength of her were-gorilla form with unpredictable spiritual intervention. Her deep rhythmic chest beats act as calls toward the spiritual plane. Gōurīrā Loa''s influence allows her to introduce chaos, sensory deception, and spiritual weight into otherwise direct physical combat.","weaponDetails":"Gemma uses African drums as spiritual instruments rather than conventional weapons. Rhythmic patterns can accompany her communion with spirits and ancestral forces.","transformations":"Were-Gorilla Form\nFull Gorilla Mode","primaryAbilities":"Ancestral Assistance\nSpirit Channeling\nEnhanced Strength\nSensory Illusions\nReality Shifting\nSpiritual Reinforcement","secondaryAbilities":"Ritual Drumming\nSpirit Communication\nEnhanced Agility\nEnhanced Durability","signatureTechniques":"Rhythmic Spirit Call\nSpiritual Chest Beat","transformationDetails":"Her were-gorilla form stands around five and a half feet tall with a compact, heavily muscled build, broad shoulders, deep chest, long powerful arms, and a tapered waist. Midnight-black fur carries subtle violet undertones, while longer golden-brown fur forms a mane around her face and neck. Her amber eyes remain expressive, crimson geometric spiritual markings glow beneath the fur along her collarbones and forearms, and a short golden tail-tuft reacts to her mood. Full Gorilla Mode becomes more completely gorilla-like while retaining her black coat, golden-brown mane, amber eyes, spiritual markings, and immense physical power."},"is_public":false,"appearance":{"build":["Tall","Slender","Graceful"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":["Black — #141114"],"skinHex":["Deep Ebony — #321F1B"],"eyeColor":["Dark brown"],"grooming":"Neatly maintained braids","skinTone":["Deep rich ebony"],"wardrobe":"Wrapper skirts\nWide-sleeved blouses\nCeremonial attire","hairColor":["Black"],"hairStyle":"Intricate tightly coiled braids","accessories":"Bone-rimmed spectacles\nCowrie shells\nPolished wooden beads\nWooden talisman necklace\nRiver stone necklace","faceDetails":["Soft features","Dreamy expression","Small upturned nose"],"hairTexture":["4C"],"colorPalette":"Ebony — #321F1B\nLinen — #E7DDC8\nWood Brown — #75543A\nRiver Stone — #68675F","dominantHand":"","outfitColors":"Natural linen\nEarth brown\nStone grey","alternateForm":["Were-Gorilla Form","Full Gorilla Mode"],"clothingStyle":"Period-appropriate African-inspired clothing emphasizing natural fabrics, flowing silhouettes, practical movement, and spiritual adornments.","appearanceNotes":"Gemma''s delicate, scholarly human appearance contrasts strongly with her powerful werebeast forms. Her visual design should maintain an ethereal, meditative quality without diminishing her underlying physical and spiritual strength.","outfitMaterials":["Linen","Cotton","Wood","River stone"],"postureMovement":["Quiet","Gliding","Grounded"],"signatureOutfit":"An undyed linen wrapper-and-blouse ensemble. The rectangular wrapper is tied at the waist as a flowing skirt, while the loose blouse has wide sleeves for comfort and movement.","distinguishingFeatures":["Bone-rimmed spectacles","Cowrie-adorned braids","Wooden hair beads"]},"created_at":"2026-09-25T18:29:48.750134+00:00","updated_at":"2026-09-25T19:25:20.8792+00:00","is_complete":true,"origin_lore":{"fears":"","goals":["Master spiritual practices","Deepen her Loa connection"],"beliefs":["Respect for ancestors","Respect for the Loa","Spiritual coexistence","Clan unity"],"culture":["Moonwoodvail","Monkey Clan","Voodoo traditions","Ancestral spirituality","African drumming traditions"],"lineage":"Royal Moonwoodvail lineage","storyArc":"Gemma''s growing understanding of Voodoo and the Loa prepares her for her destined union with Gōurīrā Loa. This bond expands her abilities from ancestral assistance into powerful spiritual chaos, illusion, and reality manipulation.","backstory":"Gemma was born into Moonwoodvail''s royal family as a daughter of King Kaelo and the Queen of the Monkey Clan. She developed a deep fascination with Voodoo, the Loa, ancestral spirits, and ritual practices. Her spiritual studies eventually became inseparable from her combat abilities and drumming.","childhood":"","lifestyle":["Studies Voodoo","Studies the Loa","Plays African drums","Practices spiritual rituals"],"storyRole":"Gemma serves as a spiritual bridge between Moonwood Vail''s physical and spiritual worlds. Her scholarship and connection to Gōurīrā Loa give her a distinct role among King Kaelo''s children.","birthplace":"Moonwood Vail","psychology":["Spiritually inquisitive","Deeply contemplative","Comfortable with the unseen"],"motivations":["Understand the Loa","Preserve ancestral knowledge","Protect Moonwood Vail","Serve her clan"],"personality":["Intelligent","Dreamy","Studious","Calm","Grounded","Playful","Mischievous","Spiritually curious"],"voiceSpeech":["Soft-spoken","Thoughtful","Playful when relaxed"],"likesDislikes":["Voodoo","Loa","African drums","Ancestral knowledge","Spiritual study"],"majorLifeEvents":"Studied Voodoo\nStudied the Loa\nBecame a spiritual intermediary\nChosen by Gōurīrā Loa"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/60e6b4b0-fa5e-46ed-b202-7d8cea244f87/portrait/1790364214194-gemma-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nCalliope\nHuxleigh\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Gemma''s mother is the Queen of the Monkey Clan, but her personal name has not been established. Gemma is one of King Kaelo''s seven children."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"97cc57ef-5f5b-4011-95ed-481f61480c26","faction_record_id":"43c09341-d62a-4297-adba-d3e083f3e202"}', '2026-09-25 19:27:18.283644+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('3ca38daa-168b-46ed-bae7-221fb74cb7da', 'studio_characters', '27d2993d-dc47-4027-9d2d-d0daed6b43c2', 'Peregrine', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"27d2993d-dc47-4027-9d2d-d0daed6b43c2","name":"Peregrine","media":{"tbdFields":"Age\nBirth date\nPronunciation\nName meaning\nExact height\nExact weight\nDominant hand\nMother\nPartner\nAllies\nRivals\nEnemies\nMentors\nExact dagger design\nExact illusion techniques\nIllusion limitations","canonLocks":"Male\nHe/Him\nKing Kaelo''s son\nOne of seven siblings\nMoonwood Vail\nWerebeast\nWarm caramel skin\nLoose 4C afro\nLithe slender build\nShortest older sibling\nIllusion mastery\nDeception mastery\nDaggers\nFox-Dire Wolf form\nSmaller werebeast form\nRed and caramel fur\nDark grey paws","galleryUrl":"","mediaNotes":"Existing artwork establishes Peregrine''s human appearance, fantasy clothing, daggers, expressions, and Fox-Dire Wolf werebeast design. Future artwork should preserve the established visual continuity.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/27d2993d-dc47-4027-9d2d-d0daed6b43c2/portrait/1790364115845-peregrine-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"Maintain Peregrine''s established anime/fantasy design across future artwork. His human form must remain lithe, slender, warm caramel-skinned, sharp-featured, and characterized by loose 4C hair. His werebeast form must remain smaller than his siblings'' forms and preserve its red, caramel, and dark grey coloration.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/27d2993d-dc47-4027-9d2d-d0daed6b43c2/reference/1790364122249-peregrine-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/27d2993d-dc47-4027-9d2d-d0daed6b43c2/alternate/1790364130239-peregrine-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Peregrine","race":"Werebeast","alias":"","gender":"Male","titles":"Prince of Moonwood Vail","subrace":"Fox-Dire Wolf Werebeast","summary":"Peregrine is a lithe and cunning prince of Moonwood Vail whose strengths lie in agility, deception, and illusion. Smaller than his older siblings, he developed a competitive streak and a constant need to prove that he is every bit as dangerous. He carries himself with sly confidence, natural elegance, and a sharp awareness of his surroundings.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Prince","affiliation":"Moonwood Vail Royal Family","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"Daggers","strengths":"Agility\nSpeed\nCunning\nDeception\nObservation\nIllusion\nQuick thinking","weaknesses":"Smaller stature\nCompetitive pride\nNeed to prove himself","combatStyle":["Agile","Deceptive","Evasive","Dagger-based","Misdirection-focused","Precision-focused"],"limitations":["Less physically imposing","Illusion limits unestablished"],"powerSource":["Werebeast nature","Illusion mastery"],"abilityNotes":"Peregrine is established as a master of deception and illusion. Exact illusion techniques, ranges, costs, and restrictions have not yet been established.","combatProfile":"Peregrine favors speed, misdirection, illusions, and precision over direct contests of strength. His quick movements and deceptive tactics keep opponents uncertain of his true position and intentions. His smaller werebeast form further emphasizes agility rather than overwhelming physical power.","weaponDetails":"Peregrine carries daggers at his waist for fast, precise attacks that complement his agile fighting style. Their exact design and number have not been established.","transformations":"Fox-Dire Wolf Werebeast Form","primaryAbilities":"Illusion\nDeception","secondaryAbilities":"Enhanced agility\nEnhanced senses\nRapid movement\nStealth\nSharp observation","signatureTechniques":"","transformationDetails":"Peregrine''s werebeast form is approximately the size of a large fox, making him smaller than his siblings'' werebeast forms. It combines fox-like proportions with powerful dire wolf limbs and a dense coat. His fur blends vibrant reds and warm caramel, shifting to dark grey around his dire wolf-like paws. His sharp, intelligent eyes and agile movements preserve his cunning personality in this form."},"is_public":false,"appearance":{"build":["Lithe","Slender","Lean","Agile"],"nails":"","eyeHex":["Amber Brown — #A8662B"],"height":"Medium height","makeup":"","weight":"","hairHex":["Black — #15120F"],"skinHex":["Warm Caramel — #A96845"],"eyeColor":["Amber-brown"],"grooming":"Neat and stylish","skinTone":["Warm caramel"],"wardrobe":"Short linen tunic\nFitted trousers\nLeather ankle ties\nWide leather belt\nShort shoulder cloak","hairColor":["Black"],"hairStyle":"Loose stylish afro","accessories":"Metal cloak brooch\nLeather belt\nDagger sheaths","faceDetails":["Sly fox-like face","Sharp features","Expressive brows"],"hairTexture":["4C"],"colorPalette":"Black — #151515\nDark Brown — #3A281E\nWarm Caramel — #A96845\nWarm Red — #9A3F27\nDark Grey — #3B3A3A","dominantHand":"","outfitColors":"Black\nCharcoal\nDark brown","alternateForm":["Fox-Dire Wolf Werebeast Form"],"clothingStyle":"Peregrine favors dark, lightweight garments designed for maximum movement and stealth. His clothing remains practical while retaining the understated refinement expected of Moonwood Vail nobility.","appearanceNotes":"Peregrine is the most lithe and slender of his brothers and the shortest of his older siblings. His silhouette should emphasize speed and agility rather than physical bulk. His sharp face, loose 4C afro, sly smirk, and confident bearing should remain consistent across artwork.","outfitMaterials":["Dark linen","Leather","Metal"],"postureMovement":["Natural elegance","Confident swagger","Quick movements","Graceful movements","Purposeful movements"],"signatureOutfit":"A tightly woven dark linen tunic cut short for unrestricted movement with period-appropriate trousers secured by leather ties at the ankles. A wide leather belt holds his daggers, while a short dark linen cloak is draped over one shoulder and secured with a metal brooch.","distinguishingFeatures":["Sly smirk","Fox-like features"]},"created_at":"2026-09-25T18:30:14.787091+00:00","updated_at":"2026-09-25T19:22:13.44847+00:00","is_complete":true,"origin_lore":{"fears":["Being dismissed as weak","Being overshadowed"],"goals":["Master illusion","Remain unpredictable","Prove his capability"],"beliefs":["Cunning can defeat strength","Size does not determine danger"],"culture":["Moonwood Vail","Werebeast royalty"],"lineage":"Moonwood Vail Royal Family","storyArc":"Peregrine''s established internal conflict centers on his need to prove that his smaller stature does not make him less dangerous or capable than his siblings. Further story developments remain unestablished.","backstory":"Peregrine grew into a clever and agile member of Moonwood Vail''s royal family. His smaller stature became both an insecurity and a driving force, pushing him toward mastery of illusion and deception. He learned to make unpredictability, speed, and intelligence more dangerous than brute strength.","childhood":"Growing up smaller than his older siblings contributed to Peregrine''s competitive nature and strong need to prove himself. Rather than relying on physical size, he developed cunning, agility, wit, and deception as his defining strengths.","lifestyle":["Practices agility","Practices deception","Maintains mobility-focused clothing"],"storyRole":"Peregrine represents cunning, deception, and agility among King Kaelo''s children. His smaller stature distinguishes him from his physically larger siblings and encourages him to approach danger through intelligence, misdirection, and speed.","birthplace":"Moonwood Vail","psychology":["Short guy complex","Needs to prove himself","Dislikes underestimation","Highly competitive"],"motivations":["Prove his worth","Outsmart stronger opponents","Match his siblings"],"personality":["Cunning","Competitive","Confident","Sly","Clever","Observant","Free-spirited","Prideful","Witty"],"voiceSpeech":["Sharp wit","Confident delivery","Playful taunting"],"likesDislikes":["Likes competition","Likes clever victories","Likes proving himself","Dislikes being underestimated","Dislikes size comparisons"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/27d2993d-dc47-4027-9d2d-d0daed6b43c2/portrait/1790364115845-peregrine-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nHuxleigh\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Peregrine is one of King Kaelo''s seven children. His smaller stature compared with his older siblings contributes to his competitive personality and desire to prove himself."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"615fa3ab-4f1d-47f0-b4f3-5e94e4fbf5fe","faction_record_id":"ec408c98-c948-442c-9c14-74dd07dde097"}', '2026-09-25 19:27:19.126065+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('46dafa15-1ae8-45cf-b05b-5f2882ad19cb', 'studio_characters', 'b317848b-4cba-46fa-8807-4c9ffd26392e', 'Herabelle', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"b317848b-4cba-46fa-8807-4c9ffd26392e","name":"Herabelle","media":{"tbdFields":"Birth date\nExact age\nBirthplace\nHomeland\nCurrent residence\nParents\nSiblings\nLineage\nHeritage\nNationality\nHeight\nWeight\nDominant hand\nPartner status\nFormal affiliation","canonLocks":"Name is Herabelle\nFemale\nHuman\nBlonde hair\nGreen eyes\nBeautiful appearance\nDevoted to Alistair\nSoul-Tether\nHeart-Seeker\nWeapons forged by Alistair\nCarries her weapons with love","galleryUrl":"","mediaNotes":"Established artwork includes character portraits, a full-body combat design, visual production material, Soul-Tether and Heart-Seeker references, combat imagery, and promotional artwork. Future artwork must preserve the established blonde-haired, green-eyed Herabelle design.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b317848b-4cba-46fa-8807-4c9ffd26392e/portrait/1790364033055-herabelle-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Needed\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"Preserve Herabelle''s established blonde hair, green eyes, fair complexion, feminine face, slender athletic build, and neutral medieval-fantasy combat clothing. Soul-Tether and Heart-Seeker must follow their established visual references. Her design should emphasize beauty and elegance while allowing her obsessive combat persona to create a dramatic visual contrast.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b317848b-4cba-46fa-8807-4c9ffd26392e/reference/1790364038492-herabelle-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b317848b-4cba-46fa-8807-4c9ffd26392e/alternate/1790364048033-herabelle-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Herabelle","race":"Human","alias":"","gender":"Female","titles":"The Shadow of the Forge\nDevoted Protector","subrace":"","summary":"Herabelle is a beautiful, highly devoted protector whose loyalty to Alistair borders on worship. She serves as the finesse beside his overwhelming force, using speed, precision, and chained weaponry to control threats around him. Her affection becomes dangerous when jealousy or perceived threats to Alistair overwhelm her judgment.","heritage":"","homeland":"","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"Protector","affiliation":"","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""},"abilities":{"weapons":"Soul-Tether\nHeart-Seeker","strengths":"Speed\nAgility\nPrecision\nWeapon control\nBattlefield control\nProtective instinct","weaknesses":"Obsessive attachment\nJealousy\nEmotional instability\nPossessiveness","combatStyle":["Macabre Acrobat","Chain combat","Acrobatic movement","Precision strikes","Protective interception","Battlefield herding"],"limitations":["Emotion can override judgment","Overprotective of Alistair"],"powerSource":["Combat training","Alistair-forged weapons"],"abilityNotes":"Her combat choreography should appear graceful and rhythmic even at maximum aggression. Soul-Tether creates broad sweeping movements and unusual attack angles, while Heart-Seeker provides compact precision at close range.\n\nHerabelle is her canonical name. Do not use Lyra.","combatProfile":"Herabelle fights through finesse rather than overwhelming force. Soul-Tether controls distance and enemy movement while Heart-Seeker handles close-range precision attacks. She uses fluid acrobatics to herd enemies toward Alistair''s attacks and will physically intercept threats directed at him.","weaponDetails":"Soul-Tether is a long chained weapon crafted by Alistair for battlefield control. Its chain, crescent cutting head, and weighted component allow Herabelle to bind, trip, slow, and manipulate enemy movement. Heart-Seeker is a jagged, ultra-sharp serrated blade forged from Alistair''s kinetic-absorbing metal for close-range precision and dismantling. Herabelle carries both weapons with intense affection because Alistair made them.","transformations":"","primaryAbilities":"Chain Weapon Mastery\nBlade Mastery\nAcrobatic Combat\nEnemy Restraint\nPrecision Dismantling","secondaryAbilities":"Battlefield Control\nRapid Repositioning\nProtective Interception\nTarget Tracking","signatureTechniques":"Kinetic Synchronization\nSadist''s Grace\nHuman Shield","transformationDetails":""},"is_public":false,"appearance":{"build":["Slender","Athletic","Agile"],"nails":"","eyeHex":["Green — #6F8F65"],"height":"","makeup":["Subtle eye definition","Natural lips"],"weight":"","hairHex":["Blonde — #D8B985"],"skinHex":["Fair — #E8C9B8"],"eyeColor":["Green"],"grooming":"Feminine and carefully maintained","skinTone":["Fair"],"wardrobe":"Neutral combat attire\nDark leather armor\nIvory underlayers\nTall leather boots\nFingerless gloves","hairColor":["Blonde"],"hairStyle":"Long flowing blonde hair","accessories":"Forge-soot vial necklace\nLeather belts\nMetal chains\nForge-inspired jewelry","faceDetails":["Soft feminine features","Refined jawline","Delicate nose","Expressive eyes"],"hairTexture":["Soft","Lightly tousled"],"colorPalette":"Ivory — #E6DDD0\nCharcoal — #211F1E\nBlack — #0D0D0E\nLeather Brown — #49372C\nSteel — #A9B3BA\nRune Blue — #8DD9ED","dominantHand":"","outfitColors":"Ivory\nCharcoal\nBlack\nDark brown\nSteel","alternateForm":"","clothingStyle":"Herabelle wears elegant medieval-fantasy combat clothing built around neutral colors and dark leather. Fitted protection, layered fabrics, belts, chains, and subtle gothic detailing complement her graceful fighting style without restricting movement.","appearanceNotes":"Herabelle initially looks like an exceptionally beautiful and seemingly ordinary blonde human woman. Her green eyes become noticeably softer and gain a subtle twinkle when she looks at Alistair. Her combat expressions create a sharp contrast with her otherwise graceful appearance.","outfitMaterials":["Leather","Linen","Metal","Chain","Lace"],"postureMovement":["Graceful","Fluid","Acrobatic","Predatory"],"signatureOutfit":"A fitted neutral-toned fantasy combat ensemble with an ivory underlayer, dark leather corsetry, layered fabric, belts, straps, gloves, and tall boots. The silhouette remains feminine and elegant while allowing unrestricted acrobatic movement.","distinguishingFeatures":["Intense sanpaku gaze","Softened gaze around Alistair","Elegant combat silhouette"]},"created_at":"2026-09-25T18:32:15.632468+00:00","updated_at":"2026-09-25T19:20:51.413733+00:00","is_complete":true,"origin_lore":{"fears":["Losing Alistair","Separation from Alistair"],"goals":["Keep Alistair safe","Remain useful to Alistair","Fight beside Alistair"],"beliefs":["Alistair is extraordinary","His creations are sacred","Protection proves devotion"],"culture":"","lineage":"","storyArc":"Herabelle''s arc explores the dangerous boundary between devotion, possession, and protection. Her loyalty makes her an invaluable defender, but her distorted interpretation of Alistair''s affection can become unstable whenever she believes their bond is threatened.","backstory":"Herabelle became deeply devoted to Alistair and established herself as his protector. Her attachment developed beyond ordinary loyalty, causing her to treat his craftsmanship, words, and gifts with almost sacred reverence. She quietly handles perceived threats around him rather than burdening him with every confrontation.","childhood":"","lifestyle":["Stays near Alistair","Maintains her weapons","Watches for threats","Preserves forge keepsakes"],"storyRole":"Herabelle serves as the graceful but dangerous shadow beside Alistair. Where his forgecraft and kinetic force dominate openly, she uses speed, precision, chains, and close-range attacks to control threats before they can reach him.","birthplace":"","psychology":["Idealizes Alistair","Misreads affection","Possessive attachment","Threat fixation","Extreme devotion"],"motivations":["Protect Alistair","Remain beside Alistair","Preserve his creations","Eliminate threats"],"personality":["Devoted","Protective","Possessive","Obsessive","Elegant","Patient","Ruthless","Jealous"],"voiceSpeech":["Soft","Melodic","Tender with Alistair","Cold toward threats","Guttural when enraged"],"likesDislikes":["Alistair''s craftsmanship","Alistair''s attention","Forge keepsakes","Protecting Alistair","Disrespect toward Alistair","Threats toward Alistair"],"majorLifeEvents":"Became Alistair''s devoted protector\nReceived Soul-Tether\nReceived Heart-Seeker"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b317848b-4cba-46fa-8807-4c9ffd26392e/portrait/1790364033055-herabelle-character-portrait.png","relationships":{"allies":"Alistair","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":"Alistair is the center of Herabelle''s devotion. She views him and his forgecraft with almost religious reverence and frequently interprets practical praise or affection from him as something deeper. Soul-Tether and Heart-Seeker are especially precious to her because Alistair forged them."},"spoiler_level":"private","race_record_id":"c68d60d1-883a-4683-8000-a9cd9d0d4d2a","realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":null}', '2026-09-25 19:27:20.760561+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('a353810c-947a-40fe-80c4-5e1fde83eb61', 'studio_characters', '808d3a77-faab-458d-9d54-715ac887bb40', 'Sax', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"808d3a77-faab-458d-9d54-715ac887bb40","name":"Sax","media":{"tbdFields":"Birth date\nName meaning\nElemental heritage\nSubrace\nHeritage\nNationality\nCurrent residence\nWeight\nDominant hand\nParents'' names\nSiblings\nPartner","canonLocks":"Duskari\nMale\nMoonwoodvail origin\nSilas''s nephew\nCrimson Tide survivor\nCaptain Blackheart killed his family\nAzure Fleet destroyed his family\nVoodoo Roguery\nInvocation\nBiomancy\nTwin shadow daggers\nPurple eyes\nCornrow braids\nRed hair beads\nKaelen''s close friend\nZafir rivalry","galleryUrl":"","mediaNotes":"Future artwork must follow the established production sheet and full-body reference. Do not redesign Sax''s face, skin tone, eyes, hairstyle, physique, signature outfit, weapons, or primary palette.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/portrait/1790363965860-sax-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Done\nRight View — Needed\nFace Reference — Done\nEye Reference — Needed\nHair Reference — Needed\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"The established Reference / Production Sheet is Sax''s primary visual canon. Preserve his dark skin, purple eyes, cornrow braids with red beads, lean muscular build, fur-trimmed vest, bone ornaments, deep-red sash, skull belt piece, Voodoo dolls, feather accents, and ornate twin daggers. Spiritual blade energy should remain dark purple and black.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/reference/1790363972828-sax-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/alternate/1790363979976-sax-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"19","era":"500–1300 AD-inspired","name":"Sax","race":"Duskari","alias":"The Voodoo Assassin","gender":"Male","titles":"The Voodoo Assassin","subrace":"","summary":"Sax is a young Duskari Voodoo Assassin raised in Moonwoodvail. After Captain Blackheart and the Azure Fleet slaughtered his family, his uncle Silas took him in and trained him in Voodoo. Sax weaponized those spiritual teachings into an aggressive assassination style driven by Invocation, Biomancy, shadow magic, and curses.","heritage":"","homeland":"Moonwoodvail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Assassin","affiliation":"Umbra Crew","apparentAge":"19","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""},"abilities":{"weapons":"Twin Shadow Daggers\nVoodoo Dolls","strengths":"Extreme speed bursts\nFast reflexes\nClose-range combat\nSpiritual curses\nMental attacks\nHigh agility\nAssassination tactics","weaknesses":"Hot temper\nMental charms\nSpiritual manipulation\nImpulsiveness\nEmotional instability","combatStyle":["Voodoo Roguery","Dual-blade combat","Close-range assassination","High-speed movement","Mid-combat curse weaving","Shadow-enhanced strikes"],"limitations":["Sympathetic magic needs a connection","Blood curse requires prior contact","Spiritual Surge consumes life-force","Emotion disrupts concentration"],"powerSource":["Invocation","Biomancy","Spiritual energy","Ancestor spirits","Voodoo"],"abilityNotes":"Shadow-Cloaked Blades can temporarily disrupt Chronoessence conduits where Sax strikes. Grave Flashback overwhelms an enemy''s spiritual senses and forces traumatic memories or fears to the surface. Phantom Requiem: Thousand Curses summons spectral shadow-hands to restrain an enemy while Sax delivers a rapid sequence of shadow-cloaked strikes whose energy trails detonate in succession.","combatProfile":"Sax fights at close range rather than relying on stationary rituals. He channels Invocation through his spiritual techniques and Biomancy through his body, accelerating his muscles and nervous system with Spiritual Surge. His style combines rapid dual-blade attacks, shadow cloaking, sympathetic curses, and aggressive psychic assaults.","weaponDetails":"Sax dual-wields ornate curved daggers for rapid close-range attacks. He cloaks the blades in dark spiritual shadow capable of cutting physical targets and disrupting Chronoessence conduits. His blank Voodoo dolls become weapons for sympathetic curses after he obtains a physical connection to a target.","transformations":"","primaryAbilities":"Shadow-Cloaked Blades\nSpiritual Surge\nSympathetic Magic\nPsychomancy\nSpirit Channeling\nAncestor Communion","secondaryAbilities":"Sciomancy\nPhysical enhancement\nSpiritual tracking\nCurse weaving\nMental disruption","signatureTechniques":"Shadow-Cloaked Blades\nSpiritual Surge\nSympathetic Curse\nGrave Flashback\nPhantom Requiem: Thousand Curses","transformationDetails":""},"is_public":false,"appearance":{"build":["Lean","Athletic","Muscular","Toned"],"nails":"","eyeHex":["Vibrant Purple — #7B2CBF"],"height":"5''10\"","makeup":"","weight":"","hairHex":["Black — #111111"],"skinHex":["Dark Brown — #70472F"],"eyeColor":["Vibrant purple"],"grooming":"Neat braids with rugged styling","skinTone":["Dark brown"],"wardrobe":"Fur-trimmed vest\nLoose dark trousers\nDeep-red sash\nArm wraps\nLeg wraps\nWrapped sandals","hairColor":["Black"],"hairStyle":"Cornrow braids with loose front braids and red beads","accessories":"Animal-tooth necklace\nTooth earrings\nRed beads\nUpper-arm bands\nAnimal-skull belt buckle\nTwo Voodoo dolls\nFeather bundle\nSpiritual charms","faceDetails":["Sharp eyebrows","Angular features","Confident grin","Small sharp fangs"],"hairTexture":["Tightly coiled"],"colorPalette":"Dark Brown — #70472F\nBlack — #111111\nDeep Red — #711B1B\nBone Ivory — #DDD2BE\nSpirit Purple — #7B2CBF\nTeal — #285B69","dominantHand":"","outfitColors":"Dark brown\nBlack\nDeep red\nBone ivory\nTeal","alternateForm":"","clothingStyle":"Rugged Moonwoodvail assassin attire designed for unrestricted movement. Bone, teeth, beads, feathers, leather, and spiritual charms reinforce his Rootworker influence while preserving a fast close-combat silhouette.","appearanceNotes":"Sax''s established design uses a lean muscular silhouette with minimal armor for speed. His skull belt ornament, Voodoo dolls, bone jewelry, feather accents, braided hairstyle, and twin ornate daggers are major visual identifiers.","outfitMaterials":["Leather","Fur","Cloth","Bone","Feathers","Cord","Metal"],"postureMovement":["Predatory","Agile","Fast","Combat-ready"],"signatureOutfit":"Sax wears an open sleeveless brown vest with fur trim, bone fasteners, loose dark trousers, arm wraps, rugged leg wraps, and a deep-red waist sash. An animal skull decorates his belt, two Voodoo dolls hang at his waist, and a feather bundle adds red, white, and teal accents.","distinguishingFeatures":["Small fangs","Red hair beads","Tooth earrings","Bone ornaments"]},"created_at":"2026-09-25T18:35:28.28368+00:00","updated_at":"2026-09-25T19:19:44.298001+00:00","is_complete":true,"origin_lore":{"fears":["Losing another family","Failing his loved ones","Mental manipulation"],"goals":["Kill Captain Blackheart","Protect the Umbra Crew","Master Voodoo Roguery"],"beliefs":["Respect the ancestors","Protect those you love","Loyalty demands action"],"culture":["Moonwoodvail","Rootworking","Voodoo","Ancestor communion","Crossroads spirituality"],"lineage":"Duskari","storyArc":"Sax begins as a young fighter consumed by vengeance against Captain Blackheart. Training under Silas gradually forces him to refine his volatile emotions into disciplined spiritual combat. His bond with Kaelen and the Umbra Crew gives him people to protect beyond the family he lost.","backstory":"Captain Blackheart and the Azure Fleet slaughtered Sax''s family during the Crimson Tide Tragedy. Sax survived because his mother hid him during the raid. His uncle Silas took custody of him and attempted to teach him the healing and protective traditions of Voodoo, but Sax''s desire for vengeance led him to weaponize those teachings into an assassination-focused fighting style.","childhood":"Sax grew up in Moonwoodvail alongside Asha, Keno, Mali, and Rico. Their tight-knit peer group gave him a strong sense of community despite his naturally hot temper. His childhood ended violently when Captain Blackheart and the Azure Fleet attacked his coastal village.","lifestyle":["Aggressive combat training","Spiritual practice","Target hunting","Traveling with the Umbra Crew"],"storyRole":"Sax is an emotional lightning rod within the early Umbra Crew and one of Kaelen''s first true friends. His clear desire for vengeance contrasts with Kaelen''s uncertainty about his missing memories. Sax''s hatred of corruption pushes the group forward while his fierce loyalty helps keep Kaelen grounded.","birthplace":"Moonwoodvail","psychology":["Trauma-driven anger","Survivor grief","Vengeance fixation","Protective attachment","Emotionally reactive"],"motivations":["Avenge his family","Protect Kaelen","Destroy the Azure Fleet","Master his spiritual power"],"personality":["Hot-tempered","Fiercely loyal","Brash","Impulsive","Protective","Vengeful","Determined","Gritty","Competitive"],"voiceSpeech":["Blunt","Sharp","Emotionally charged","Quick-tempered"],"likesDislikes":["His crew","Challenges","Spicy food","Silas''s old stories","Dislikes vampires","Dislikes betrayal","Dislikes corrupt authority","Hates being tricked"],"majorLifeEvents":"Childhood in Moonwoodvail\nCrimson Tide Tragedy\nFamily slaughtered\nSurvived the Azure Fleet raid\nTaken in by Silas\nTrained in Voodoo\nBegan hunting Captain Blackheart\nMet Kaelen at Sunstone Coast\nJoined forces with Kaelen\nReturned to Moonwoodvail with Kaelen\nTrained under Silas"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/portrait/1790363965860-sax-character-portrait.png","relationships":{"allies":"Kaelen Thorne\nAsha\nKeno\nMali\nUmbra Crew","rivals":"Zafir\nRico","enemies":"Captain Blackheart\nAzure Fleet","mentors":"Silas\nMama Eve","parents":"","partner":"","children":"","siblings":"","worldConnections":"Moonwoodvail\nSunstone Coast\nAethelgard","relationshipNotes":"Silas is Sax''s uncle and primary Voodoo mentor, taking custody of him after the destruction of his family. Kaelen becomes Sax''s first close companion after they fight Blackheart''s thugs together near the Sunstone Coast, and Sax becomes fiercely protective of him. Sax has an explosive rivalry with Zafir, whose teasing and mini-form antics regularly provoke him. Asha, Keno, Mali, and Rico belong to Sax''s childhood Moonwoodvail peer group."},"spoiler_level":"private","race_record_id":"baaf3d0d-afe5-4ad3-92e2-14dbe7cbd5e0","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"0b04c5a0-22fd-4442-a86d-eea0aeb15514","faction_record_id":"bd19189f-d8ba-4190-af7a-4c9df16e50c9"}', '2026-09-25 19:27:21.506892+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('4fe8648c-6170-497f-aa87-98f6af7a9ab1', 'studio_characters', '37c82673-519e-4ab9-bcea-ed600577eec0', 'Huxleigh', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"37c82673-519e-4ab9-bcea-ed600577eec0","name":"Huxleigh","media":{"tbdFields":"Pronunciation\nName meaning\nBirth date\nSpoiler level\nHeritage\nNationality\nOccupation\nHeight\nWeight\nDominant hand\nSignature outfit\nAccessories\nChildhood\nMajor life events\nGoals\nFears\nBeliefs\nStory arc\nWeapons\nSignature techniques\nWeaknesses\nLimitations\nPartner\nAllies\nRivals\nEnemies\nMentors","canonLocks":"Male\nMid 20s\nKing Kaelo''s son\nOne of seven children\nMoonwood Vail\nRich dark-brown skin\nAmber eyes\nShort thick 4C hair\nFaded sides\nLarge powerful build\nPolar bear / dire wolf hybrid\nWhite and silver beast fur\nGray beast undertones\nLong dire wolf snout\nControlled rage","galleryUrl":"","mediaNotes":"Existing human and werebeast artwork establishes Huxleigh''s visual identity. Generated image text, weapons, tattoos, abilities, measurements, affiliations, or clothing details not established in written canon should not be treated as canon.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/37c82673-519e-4ab9-bcea-ed600577eec0/portrait/1790363860158-huxleigh-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Needed\nExpression Sheet — Done\nCombat Reference — Needed","productionNotes":"Future artwork must preserve Huxleigh''s established anime/fantasy design. Human artwork should retain his dark-brown skin, amber eyes, short thick 4C curls with faded sides, rugged face, broad shoulders, and dense muscular build. Werebeast artwork must preserve the polar bear scale, dire wolf anatomy, white and silver fur with gray tones, elongated muzzle, and amber eyes.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/37c82673-519e-4ab9-bcea-ed600577eec0/reference/1790363867954-huxleigh-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/37c82673-519e-4ab9-bcea-ed600577eec0/alternate/1790363873642-huxleigh-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Mid 20s","era":"500–1300 AD-inspired","name":"Huxleigh","race":"Werebeast","alias":"","gender":"Male","titles":"","subrace":"Polar Bear / Dire Wolf Hybrid","summary":"Huxleigh is one of King Kaelo''s seven children and a powerful werebeast of Moonwood Vail. Large, broad-shouldered, and physically imposing, he carries himself with intimidating confidence and controlled strength. His gruff exterior and frequent scowl conceal a mischievous sense of humor. His werebeast form combines the immense scale of a polar bear with the lean musculature and long snout of a dire wolf.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"Moonwood Vail Royal Family","apparentAge":"Mid 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Immense physical power\nDense musculature\nControlled brute force\nPhysical intimidation\nStrong self-control","weaknesses":"","combatStyle":["Brute force","Direct attacks","Heavy strikes","Controlled aggression"],"limitations":"","powerSource":["Werebeast physiology"],"abilityNotes":"No elemental magic, cryokinesis, magical weapons, or other supernatural abilities beyond his established werebeast traits have been confirmed.","combatProfile":"Huxleigh fights through overwhelming physical power and direct aggression while maintaining deliberate control. His tremendous weight and strength do not eliminate his grace or precision. His werebeast form greatly emphasizes close-range physical dominance.","weaponDetails":"","transformations":"Polar Bear / Dire Wolf Form","primaryAbilities":"Werebeast Transformation\nEnhanced Strength\nEnhanced Durability","secondaryAbilities":"Enhanced Senses","signatureTechniques":"","transformationDetails":"Huxleigh becomes a monstrous quadrupedal werebeast the size of an enormous polar bear. His form retains a lean, muscular dire wolf structure and long predatory snout beneath thick white, silver, and gray fur. His amber eyes remain prominent. His growl becomes a deep rumble, while his demeanor shifts toward controlled rage and immense brute force restrained by conscious will."},"is_public":false,"appearance":{"build":["Large","Broad-shouldered","Dense","Powerful","Muscular"],"nails":"","eyeHex":["Amber — #D88924"],"height":"","makeup":"","weight":"","hairHex":["Black — #11100F"],"skinHex":["Dark Brown — #4A2B20"],"eyeColor":["Amber"],"grooming":"","skinTone":["Rich dark brown"],"wardrobe":"","hairColor":["Black"],"hairStyle":"Short dense curls with faded sides","accessories":"","faceDetails":["Rugged handsome features","Strong jawline","Straight nose","Deep-set eyes"],"hairTexture":["4C","Thick","Tightly curled"],"colorPalette":"Dark Brown — #4A2B20\nBlack — #11100F\nAmber — #D88924\nPolar White — #EEEDE8\nSilver — #BFC2C5\nWolf Gray — #777A7D","dominantHand":"","outfitColors":"","alternateForm":["Monstrous polar bear scale","Dire wolf physique","Long dire wolf snout","White fur","Silver fur","Gray undertones","Thick matted coat"],"clothingStyle":"","appearanceNotes":"Huxleigh''s human form should emphasize dense physical strength rather than exaggerated bulk. His werebeast form is enormous and quadrupedal, combining polar bear mass with the leaner muscular structure and elongated muzzle of a dire wolf. The hybrid silhouette must clearly communicate both bloodlines.","outfitMaterials":"","postureMovement":["Heavy","Direct","Controlled","Graceful","Self-assured"],"signatureOutfit":"","distinguishingFeatures":["Intimidating scowl","Powerful physique"]},"created_at":"2026-09-25T18:35:44.284815+00:00","updated_at":"2026-09-25T19:18:49.758136+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"King Kaelo''s bloodline","storyArc":"","backstory":"Huxleigh is one of King Kaelo''s seven children and belongs to the royal family of Moonwood Vail. Further personal history has not yet been established.","childhood":"","lifestyle":"","storyRole":"Huxleigh is a member of King Kaelo''s royal family and one of his seven children. His larger individual role remains unestablished.","birthplace":"Moonwood Vail","psychology":["Controlled aggression","Strong self-control","Hidden playful streak"],"motivations":"","personality":["Self-assured","Confident","Gruff","Intimidating","Controlled","Mischievous"],"voiceSpeech":["Deep","Gruff","Direct"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/37c82673-519e-4ab9-bcea-ed600577eec0/portrait/1790363860158-huxleigh-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Huxleigh is one of King Kaelo''s seven children. Individual relationship dynamics with his siblings have not yet been established."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"54d24391-3ed4-445b-8bfe-8dba238fc8e0","faction_record_id":"ec408c98-c948-442c-9c14-74dd07dde097"}', '2026-09-25 19:27:22.192744+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('e5cf2994-a28d-42b8-8c84-6f1fab9a370e', 'studio_characters', '34b16e35-6625-4143-b97b-a3b628d60617', 'Calliope', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"34b16e35-6625-4143-b97b-a3b628d60617","name":"Calliope","media":{"tbdFields":"Mother\nBirth date\nHeight\nWeight\nDominant hand\nOccupation\nWeapons\nSignature techniques\nWeaknesses\nAbility limitations\nPartner\nStory role\nStory arc","canonLocks":"Female\nLate 20s\nKing Kaelo''s child\n4C hair\nThick long locs\nLioness/Dire Wolf hybrid\nTawny-gold werebeast coat\nDire wolf-like legs and paws\nFeminine werebeast form\nNo male lion mane\nMoonwood Vail","galleryUrl":"","mediaNotes":"Human-form character artwork and werebeast-form artwork are established visual references. The future Reference / Production Sheet should consolidate these designs into the primary visual canon reference.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/34b16e35-6625-4143-b97b-a3b628d60617/portrait/1790363775772-calliope-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Needed\nAlternate / True Form — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Needed\nEye Reference — Needed\nHair Reference — Needed\nOutfit Breakdown — Needed\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Preserve Calliope''s established anime/fantasy design across all future artwork. Her human form must retain the same facial structure, deep-brown skin, golden-amber eyes, black 4C locs, feminine athletic build, and dark-and-gold visual identity. Her werebeast form must remain a feminine lioness/dire wolf hybrid with a tawny-gold coat, powerful dire wolf-like legs and paws, and no male lion mane.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/34b16e35-6625-4143-b97b-a3b628d60617/reference/1790363780954-calliope-reference-production-shee.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/34b16e35-6625-4143-b97b-a3b628d60617/alternate/1790363787036-calliope-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Late 20s","era":"500–1300 AD-inspired","name":"Calliope","race":"Werebeast","alias":"","gender":"Female","titles":"","subrace":"Lioness/Dire Wolf Hybrid","summary":"Calliope is one of King Kaelo''s seven children. Fierce, intelligent, confident, and competitive, she carries herself with quiet authority and the controlled grace of a huntress. Her werebeast form combines the grace of a lioness with the powerful legs and heavy paws of a dire wolf.","heritage":"","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"Late 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Physical Strength\nAgility\nSpeed\nPredatory Senses\nPouncing Power","weaknesses":"","combatStyle":["Predatory","Fluid","Close-range","Pounce-focused"],"limitations":"","powerSource":["Werebeast physiology"],"abilityNotes":"","combatProfile":"Calliope fights with fluid, purposeful aggression modeled on a large hunting predator. Her werebeast form emphasizes explosive pounces, powerful limbs, heavy paws, claws, fangs, and close-range physical attacks.","weaponDetails":"","transformations":"Lioness/Dire Wolf Werebeast Form","primaryAbilities":"Werebeast Transformation\nEnhanced Strength\nEnhanced Agility\nEnhanced Speed\nPredatory Senses","secondaryAbilities":"Natural Claws\nNatural Fangs\nPowerful Pounce","signatureTechniques":"","transformationDetails":"Calliope becomes a quadrupedal werebeast approximately the size of a full-grown lioness. Her form has a rich tawny-gold coat, lioness proportions, powerful dire wolf-like legs, and heavy paws. A thick shaggy ruff covers the neck and shoulders, but she has no male lion mane. Her eyes retain the fierce intelligence and predatory focus of her human form."},"is_public":false,"appearance":{"build":["Athletic","Powerful","Feminine"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":["Black — #0B0908"],"skinHex":"","eyeColor":["Golden amber"],"grooming":"","skinTone":["Deep brown"],"wardrobe":"Regal attire\nCombat attire","hairColor":["Black"],"hairStyle":"Thick majestic locs framing her face and falling down her back.","accessories":"Gold hair cuffs\nGold earrings\nGold jewelry","faceDetails":["Long face","Angular features","Confident chin"],"hairTexture":["4C"],"colorPalette":"Black — #0B0908\nTawny Gold\nDark Brown\nGold","dominantHand":"","outfitColors":"Black\nGold","alternateForm":["Lioness/Dire Wolf Werebeast"],"clothingStyle":"Regal fantasy clothing with dark fabrics, gold detailing, and practical construction suited to movement and combat.","appearanceNotes":"Calliope''s human design emphasizes strength, femininity, and predatory confidence. Her thick 4C locs visually echo the powerful silhouette associated with her lioness heritage without becoming a literal mane.","outfitMaterials":["Cloth","Leather","Metal"],"postureMovement":["Fluid","Purposeful","Predatory","Commanding"],"signatureOutfit":"Regal dark fantasy attire with gold detailing, fitted for mobility and a commanding silhouette.","distinguishingFeatures":["Thick long locs","Confident smirk"]},"created_at":"2026-09-25T18:37:15.885714+00:00","updated_at":"2026-09-25T19:17:23.565899+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"King Kaelo''s bloodline","storyArc":"","backstory":"Calliope is one of King Kaelo''s seven children of Moonwood Vail. She developed a fierce, competitive temperament and carries herself with natural authority. Her movements and demeanor reflect the instincts of a patient, confident huntress.","childhood":"","lifestyle":"","storyRole":"","birthplace":"Moonwood Vail","psychology":["Strong-willed","Self-assured","Competitive"],"motivations":"","personality":["Confident","Fierce","Intelligent","Competitive","Authoritative","Fiery"],"voiceSpeech":["Confident","Commanding"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/34b16e35-6625-4143-b97b-a3b628d60617/portrait/1790363775772-calliope-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nHuxleigh\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Calliope is one of King Kaelo''s seven children. Her established siblings are Cosmo, Gemma, Huxleigh, Peregrine, Venny''Claire, and Venny''Macon."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"54d24391-3ed4-445b-8bfe-8dba238fc8e0","faction_record_id":null}', '2026-09-25 19:27:23.933496+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('a1286d6c-977f-49ae-be62-d3015d757e2c', 'studio_characters', '263952e8-6fc5-4a74-845f-374026eaf29d', 'Cosmo', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"263952e8-6fc5-4a74-845f-374026eaf29d","name":"Cosmo","media":{"tbdFields":"Eye color\nHeight\nWeight\nBirth date\nMother\nPartner","canonLocks":"Deep warm mahogany skin\nBlack 4C hair\nNeatly kept tight coils\nStrong defined features\nChiseled jawline\nHigh cheekbones\nTall muscular build\nSerious unwavering gaze\nAfrican-inspired clothing\nWolf ancestral symbolism\nDire Wolf Form\nUpright Sudoform\nCrystal-hardened fur","galleryUrl":"","mediaNotes":"Existing visual references establish Cosmo''s human appearance, upright sudoform, dire wolf form, and multiple crystal transformations.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/263952e8-6fc5-4a74-845f-374026eaf29d/portrait/1790363585841-cosmo-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nSudoform — Done\nBurmese Tourmaline Form — Done\nAmethyst Form — Done\nObsidian Form — Done\nRuby Form — Done\nEmerald Form — Done\nRaw Diamond Form — Done\nWulfenite Form — Done\nBlack Rainbow Titanium Quartz Form — Done\nSapphire Form — Done\nRose Quartz Form — Done\nCitrine Form — Done\nAura Quartz Form — Done\nMystic Topaz Form — Done\nDioptase Form — Done","productionNotes":"Maintain Cosmo''s established human design, African-inspired ancestral clothing, powerful physique, upright sudoform, dire wolf anatomy, and crystal-hardened fur across transformation references. Individual crystal forms should visually reflect the consumed material while preserving Cosmo''s recognizable silhouette and wolf anatomy.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/263952e8-6fc5-4a74-845f-374026eaf29d/reference/1790363591989-cosmo-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/263952e8-6fc5-4a74-845f-374026eaf29d/alternate/1790363598396-cosmo-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Late 20s","era":"","name":"Cosmo","race":"Werebeast","alias":"","gender":"Male","titles":"Prince of Moonwood Vail\nHeir to Moonwood Vail","subrace":"Dire Wolf","summary":"Cosmo is King Kaelo''s eldest child and a disciplined royal heir of Moonwood Vail. Serious, resourceful, and intellectually minded, he carries responsibility with a controlled presence that reflects the immense dire wolf power beneath his calm exterior. Blessed by Terrax, he commands minerals and sand and can consume crystals to assume specialized crystalline forms.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Royal heir","affiliation":"Wolf Clan","apparentAge":"Late 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Physical strength\nDiscipline\nMineral control\nDefensive combat\nCombat adaptability\nCrystal versatility","weaknesses":"","combatStyle":["Shadow Boxing","Feints","Misdirection"],"limitations":["Crystal forms require consumed material"],"powerSource":["Dire Wolf physiology","Terrax''s blessing","Consumed crystals","Consumed gemstones"],"abilityNotes":"Cosmo can draw minerals from the earth and shape them into weapons and defensive crystal structures. He can manipulate sand into quicksand and animate it into duplicates of himself. His crystal assimilation ability lets him consume different crystals or gemstones and transform his body into corresponding crystalline forms.","combatProfile":"Cosmo combines disciplined physical combat with Shadow Boxing, smooth feints, and misdirection. His mineral and sand manipulation expands his battlefield control through weapons, crystalline defenses, quicksand, and animated sand duplicates. Crystal assimilation allows him to alter his body and dire wolf form according to the gemstone he has consumed.","weaponDetails":"","transformations":"Dire Wolf Form\nSudoform\nBurmese Tourmaline Form\nAmethyst Form\nObsidian Form\nRuby Form\nEmerald Form\nRaw Diamond Form\nWulfenite Form\nBlack Rainbow Titanium Quartz Form\nSapphire Form\nRose Quartz Form\nCitrine Form\nAura Quartz Form\nMystic Topaz Form\nDioptase Form","primaryAbilities":"Mineral Manipulation\nSand Manipulation\nCrystal Assimilation\nCrystal Transformation","secondaryAbilities":"Mineral Extraction\nMineral Weapon Creation\nCrystalline Defense\nQuicksand Creation\nSand Duplication","signatureTechniques":"Sand Duplicates\nCrystal Incasing","transformationDetails":"Cosmo possesses a dire wolf form and an upright humanoid sudoform. After consuming a compatible crystal or gemstone, he gains access to a transformation based on that material. His body becomes encased and hardened in the consumed crystal, including his dire wolf fur, which transforms into hardened crystalline fur. Each consumed material produces a visually distinct crystal form."},"is_public":false,"appearance":{"build":["Tall","Muscular","Powerful"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":"","grooming":"Neatly maintained","skinTone":["Deep warm mahogany"],"wardrobe":"African-inspired royal clothing\nWolf ancestral regalia","hairColor":["Black"],"hairStyle":"Neatly kept tight coils","accessories":"","faceDetails":["Chiseled jawline","High cheekbones","Strong defined features"],"hairTexture":["4C","Tightly coiled"],"colorPalette":"","dominantHand":"","outfitColors":"","alternateForm":["Dire Wolf Form","Sudoform","Burmese Tourmaline Form","Amethyst Form","Obsidian Form","Ruby Form","Emerald Form","Raw Diamond Form","Wulfenite Form","Black Rainbow Titanium Quartz Form","Sapphire Form","Rose Quartz Form","Citrine Form","Aura Quartz Form","Mystic Topaz Form","Dioptase Form"],"clothingStyle":"Traditional African-inspired royal attire incorporating ancestral wolf symbolism and designs suited to his position within Moonwood Vail.","appearanceNotes":"Cosmo''s human appearance emphasizes discipline and contained physical power. His dire wolf nature remains visually suggested through his commanding posture and ancestral clothing even before transformation.","outfitMaterials":"","postureMovement":["Controlled","Still","Commanding"],"signatureOutfit":"African-inspired royal clothing decorated with symbols honoring his wolf ancestors.","distinguishingFeatures":["Serious unwavering gaze","Rare grimace-like smile"]},"created_at":"2026-09-25T18:37:36.786627+00:00","updated_at":"2026-09-25T19:15:51.089199+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail","Wolf Clan"],"lineage":"Moonwood Vail royal family","storyArc":"","backstory":"Cosmo was born into King Kaelo''s royal family and raised beneath the responsibilities attached to Moonwood Vail''s Wolf Clan. He was blessed by Terrax, gaining control over minerals and sand. His supernatural physiology also allows him to consume crystals and gemstones and temporarily embody their crystalline properties.","childhood":"","lifestyle":"","storyRole":"Cosmo is the eldest royal child of King Kaelo and heir to Moonwood Vail, carrying the responsibilities of leadership while developing his inherited and bestowed powers.","birthplace":"","psychology":["Burdened by responsibility","Emotionally restrained"],"motivations":["Protect his people","Honor his ancestors"],"personality":["Serious","Disciplined","Resourceful","Intellectual","Reserved","Responsible"],"voiceSpeech":["Few words","Controlled"],"likesDislikes":"","majorLifeEvents":"Blessed by Terrax"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/263952e8-6fc5-4a74-845f-374026eaf29d/portrait/1790363585841-cosmo-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Gemma\nCalliope\nHuxleigh\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":""},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"615fa3ab-4f1d-47f0-b4f3-5e94e4fbf5fe","faction_record_id":"a289d101-2da7-4f15-bfba-51c034e5fda3"}', '2026-09-25 19:27:24.907352+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('94ccbef8-1570-46b6-940a-3add319e0f43', 'studio_characters', '3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a', 'Vorlenien "Vorlag" Hochmeister', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a","name":"Vorlenien \"Vorlag\" Hochmeister","media":{"tbdFields":"","canonLocks":"Black hair\nPiercing blue eyes\nTall build\nLean-muscular build\nBroad shoulders\nRegal presence","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a/portrait/1790363520697-vorlag-character-portrait.png","visualAssets":"Character Portrait — Done","productionNotes":"","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a/reference/1790363526757-vorlag-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a/alternate/1790363531960-vorlag-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Vorlenien \"Vorlag\" Hochmeister","race":"","alias":"King","gender":"Male","titles":"King of Shadowfen","subrace":"","summary":"King Vorlenien \"Vorlag\" Hochmeister is the ruler of Shadowfen and wielder of the great runic magic inherited through his male bloodline. After his noble family was stripped of its status and later massacred in a fire secretly orchestrated by The Church, his dormant runic power awakened through overwhelming trauma. Raised and manipulated by The Church afterward, Vorlag pursued vengeance, power, and kingship while believing the prophecy surrounding his Runes of Dominion represented his true destiny.","heritage":"","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"Vorlag","occupation":"King","affiliation":"Shadowfen","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Shadowfen","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Exceptional intellect\nRunic power\nStrategic planning\nStrong will\nPolitical authority","weaknesses":"Unresolved trauma\nFear of helplessness\nProtective obsession\nSusceptibility to Church manipulation","combatStyle":"","limitations":["Runes were initially uncontrollable"],"powerSource":["Hochmeister bloodline","Great Runic Magic"],"abilityNotes":"The great runic magic passes through the male Hochmeister bloodline. Vorlag''s abilities remained dormant until the destruction of his family triggered their violent awakening at age twelve.","combatProfile":"Vorlag possesses powerful hereditary runic magic awakened through extreme trauma. His Runes of Dominion form the supernatural foundation of his authority and are central to the prophecy cultivated around him by The Church.","weaponDetails":"","transformations":"","primaryAbilities":"Runic Magic\nRunes of Dominion","secondaryAbilities":"","signatureTechniques":"","transformationDetails":""},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Broad-shouldered"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Piercing blue"],"grooming":"","skinTone":["Pale"],"wardrobe":"","hairColor":["Black"],"hairStyle":"","accessories":"","faceDetails":["Sharp jawline","Angular features","Strong brows"],"hairTexture":"","colorPalette":"","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"","appearanceNotes":"","outfitMaterials":"","postureMovement":["Regal","Controlled","Commanding"],"signatureOutfit":"","distinguishingFeatures":""},"created_at":"2026-09-25T18:39:22.116779+00:00","updated_at":"2026-09-25T19:12:20.583307+00:00","is_complete":true,"origin_lore":{"fears":["Losing his family","Powerlessness","Failing to protect Theron","Losing control"],"goals":["Secure Shadowfen","Strengthen his rule","Fulfill his perceived destiny"],"beliefs":["Power ensures protection","Control prevents chaos","His runes mark his destiny","He is destined to rule"],"culture":"","lineage":"Hochmeister noble bloodline","storyArc":"Vorlag''s tragedy begins with a child desperate to protect his family and develops into a ruler who equates safety with absolute control. His vengeance and rise to power appear self-directed, but both were cultivated by The Church. The eventual truth behind his family''s massacre threatens the foundation of his identity, kingship, and belief in his destiny.","backstory":"At twelve, Vorlag returned with Vex, Corvin Sterling, and Alistar Vane to find the Hochmeister home engulfed in flames. Hearing his family trapped inside triggered the violent awakening of his inherited runic magic, forcing Vex to knock him unconscious before the uncontrolled eruption worsened. The massacre had secretly been engineered by The Church to awaken Vorlag''s power and advance a prophecy surrounding the Runes of Dominion. Church agents subsequently sheltered and trained him while directing his vengeance toward the nobles they had used as puppets. Vorlag eventually rose to kingship, married Isolde, established Shadowfen as his seat of power, and extended his influence into Ironspire Hold and the Lionheart Plains while remaining unaware of the full extent of The Church''s manipulation.","childhood":"Vorlag was born into a high-ranking noble family and displayed exceptional intellect from childhood. At age six, rival nobles stripped his family of its position and reduced them to commoners. He witnessed repeated humiliation and abuse directed toward his family and learned that openly resisting their aggressors could bring even greater retaliation.","lifestyle":["Royal governance","Military oversight","Runic training"],"storyRole":"Vorlag serves as the tyrannical King of Shadowfen while unknowingly remaining a central piece in The Church''s long-term plan. His rule, runic inheritance, and manipulated prophecy connect him to the artifact that Elias Thorne will eventually seek to protect.","birthplace":"","psychology":["Deep fear of helplessness","Obsessed with control","Protection through power","Unresolved family grief","Trauma-driven vigilance","Righteous self-justification"],"motivations":["Protect his family","Prevent future helplessness","Maintain absolute control","Fulfill the Dominion prophecy","Preserve Shadowfen"],"personality":["Intelligent","Calculating","Protective","Driven","Controlling","Ruthless","Traumatized","Determined","Suspicious"],"voiceSpeech":["Commanding","Controlled","Authoritative"],"likesDislikes":"","majorLifeEvents":"Born into House Hochmeister\nFamily stripped of noble status\nFamily reduced to commoners\nWitnessed repeated family abuse\nAttempted to defend his family\nHochmeister home burned\nFamily killed in the fire\nRunic magic awakened\nTaken in by The Church\nTrained by The Church\nHunted the responsible nobles\nFalsely accused of killing his family\nPursued the Dominion prophecy\nMarried Isolde\nBecame King\nEstablished Shadowfen"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a/portrait/1790363520697-vorlag-character-portrait.png","relationships":{"allies":"Count Vex\nLord Corvin Sterling\nLord Alistar Vane","rivals":"","enemies":"","mentors":"","parents":"","partner":"Isolde","children":"Theron","siblings":"","worldConnections":"Shadowfen\nIronspire Hold\nLionheart Plains","relationshipNotes":"Vex, Corvin Sterling, and Alistar Vane were Vorlag''s closest childhood friends and remained central figures in his rise. Vex helped keep him level-headed through cynical distraction, Corvin brought humor during their childhood, and Alistar provided intellectual and physical motivation. The Church later positioned itself as Vorlag''s benefactor while secretly having engineered the destruction of his family."},"spoiler_level":"private","race_record_id":null,"realm_record_id":null,"workflow_status":"draft","family_record_id":"959ee89b-1d60-47e4-b017-93d8ade67726","faction_record_id":"74fb0163-f452-4f7e-a9ea-13c15bb960db"}', '2026-09-25 19:27:26.037429+00');
INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('dc8f79fd-598c-48d1-bb14-91ffa1f3181b', 'studio_characters', 'eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478', 'Venny''Claire', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478","name":"Venny''Claire","media":{"tbdFields":"","canonLocks":"Rich warm brown skin\nDeep brown eyes\nBlack 4c hair\nWild untamed hairstyle\nCompact agile build\nNatural linen dress\nBraided leather waist cord\nLayered jewelry\nLeather sandals\nBlack werepanther form\nSilver right hind leg patch","galleryUrl":"","mediaNotes":"Official visual references include the solo human portrait, human production sheet, and black werepanther production sheet.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/portrait/1790359991558-venny-claire-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Maintain the established anime design across future artwork. Human-form references establish her youthful face, warm brown skin, deep brown eyes, wild 4c hair, compact build, linen dress, layered jewelry, braided leather waist cord, and sandals. Werebeast references establish the sleek black werepanther design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/reference/1790359997049-venny-claire-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/alternate/1790360002404-venny-claire-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Venny''Claire","race":"Werebeast","alias":"","gender":"Female","titles":"","subrace":"Werepanther","summary":"Venny''Claire is one of King Kaelo''s children and the mirror counterpart of Venny''Macon. Playful, carefree, and highly curious, she embraces movement and instinct with natural confidence. Her exceptional awareness and agility make her a swift, perceptive presence who treats the world around her as something to explore.","heritage":"Dire Wolf lineage","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Exceptional agility\nHigh speed\nHeightened awareness\nFast reflexes\nFluid movement\nAcrobatic mobility","weaknesses":"","combatStyle":["Agile","Acrobatic","Instinctive","Evasive","Speed-focused"],"limitations":"","powerSource":["Werepanther heritage","Dire Wolf lineage"],"abilityNotes":"Her heightened senses provide a constant low-level stream of sensory information that guides her movements and gives her exceptional awareness of her surroundings.","combatProfile":"Venny''Claire relies on speed, agility, instinct, and constant sensory awareness rather than overwhelming physical force. Her compact werepanther form allows rapid directional changes, fluid evasive movement, and acrobatic attacks.","weaponDetails":"","transformations":"Sudo Form\nBlack Werepanther Form","primaryAbilities":"Werepanther Transformation\nEnhanced Agility\nEnhanced Speed\nHeightened Senses","secondaryAbilities":"Enhanced Awareness\nEnhanced Reflexes\nAcrobatic Movement\nStealth","signatureTechniques":"","transformationDetails":"Venny''Claire''s full werebeast form is a sleek black werepanther with a deep, inky coat that seems to absorb light. Her smaller, compact body is built for speed, stealth, and acrobatic agility. Her only visible dire wolf trait is a silver patch of fur on her right hind leg. She moves with fluid grace and retains her playful curiosity and exceptional awareness."},"is_public":true,"appearance":{"build":["Compact","Lean","Agile"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Deep brown"],"grooming":"Natural","skinTone":["Rich warm brown"],"wardrobe":"Sleeveless linen dress\nLeather sandals","hairColor":["Black"],"hairStyle":"Wild and untamed","accessories":"Braided leather waist cord\nLayered necklaces\nBeaded jewelry\nGold earrings\nGold bracelet","faceDetails":["High cheekbones","Small symmetrical nose","Youthful features"],"hairTexture":["4c","Dense"],"colorPalette":"Warm Brown\nBlack\nNatural Linen\nLeather Brown\nGold\nSilver","dominantHand":"","outfitColors":"Natural linen\nLeather brown\nGold","alternateForm":["Black Werepanther","Sudo Form"],"clothingStyle":"Light, practical clothing that allows unrestricted movement and suits the climate of Moonwood Vail.","appearanceNotes":"Venny''Claire closely mirrors Venny''Macon in facial structure, complexion, eyes, and hair. She is smaller and more compact than her brother, with a lighter frame suited to speed, agility, and acrobatic movement.","outfitMaterials":["Woven linen","Leather","Beads","Metal"],"postureMovement":["Relaxed posture","Fluid movement","Light-footed"],"signatureOutfit":"Simple sleeveless woven linen dress secured with a braided leather waist cord and worn with leather sandals.","distinguishingFeatures":["Large wide-set eyes"]},"created_at":"2026-09-25T17:42:10.890987+00:00","updated_at":"2026-09-25T18:27:18.723591+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"Dire Wolf and Werepanther","storyArc":"","backstory":"","childhood":"","lifestyle":"","storyRole":"Venny''Claire represents instinct, curiosity, and freedom of movement. Her natural confidence and heightened awareness contrast with Venny''Macon''s uncertainty, making the twins mirrors in appearance but opposites in how they approach their abilities.","birthplace":"","psychology":["Highly instinctive","Constantly aware","Lives in the moment"],"motivations":["Exploration","Curiosity"],"personality":["Playful","Carefree","Curious","Unserious","Mischievous","Observant"],"voiceSpeech":"","likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/portrait/1790359991558-venny-claire-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nHuxleigh\nPeregrine\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Venny''Claire and Venny''Macon are mirror counterparts in appearance and temperament. Their shared features emphasize their connection, while her playful confidence and instinctive nature contrast with his reserved uncertainty."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"bbe46246-e94b-498d-9ab5-cae88e0804f7","faction_record_id":null}', '2026-09-25 19:27:28.811701+00');
