INSERT OR IGNORE INTO studio_revisions (id, entity_type, entity_id, entity_label, changed_by, changed_by_email, snapshot, created_at) VALUES ('b8bf927b-c5b0-4728-92e5-398660d662a5', 'studio_characters', 'eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478', 'Venny''Claire', 'db618e68-0656-4b9b-b308-81e071faf745', 'Bryannaparker2521@gmail.com', '{"id":"eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478","name":"Venny''Claire","media":{"tbdFields":"","canonLocks":"Rich warm brown skin\nDeep brown eyes\nBlack 4c hair\nWild untamed hairstyle\nCompact agile build\nNatural linen dress\nBraided leather waist cord\nLayered jewelry\nLeather sandals\nBlack werepanther form\nSilver right hind leg patch","galleryUrl":"","mediaNotes":"Official visual references include the solo human portrait, human production sheet, and black werepanther production sheet.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/portrait/1790359991558-venny-claire-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Maintain the established anime design across future artwork. Human-form references establish her youthful face, warm brown skin, deep brown eyes, wild 4c hair, compact build, linen dress, layered jewelry, braided leather waist cord, and sandals. Werebeast references establish the sleek black werepanther design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/reference/1790359997049-venny-claire-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/alternate/1790360002404-venny-claire-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Venny''Claire","race":"Werebeast","alias":"","gender":"Female","titles":"","subrace":"Werepanther","summary":"Venny''Claire is one of King Kaelo''s children and the mirror counterpart of Venny''Macon. Playful, carefree, and highly curious, she embraces movement and instinct with natural confidence. Her exceptional awareness and agility make her a swift, perceptive presence who treats the world around her as something to explore.","heritage":"Dire Wolf lineage","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Exceptional agility\nHigh speed\nHeightened awareness\nFast reflexes\nFluid movement\nAcrobatic mobility","weaknesses":"","combatStyle":["Agile","Acrobatic","Instinctive","Evasive","Speed-focused"],"limitations":"","powerSource":["Werepanther heritage","Dire Wolf lineage"],"abilityNotes":"Her heightened senses provide a constant low-level stream of sensory information that guides her movements and gives her exceptional awareness of her surroundings.","combatProfile":"Venny''Claire relies on speed, agility, instinct, and constant sensory awareness rather than overwhelming physical force. Her compact werepanther form allows rapid directional changes, fluid evasive movement, and acrobatic attacks.","weaponDetails":"","transformations":"Sudo Form\nBlack Werepanther Form","primaryAbilities":"Werepanther Transformation\nEnhanced Agility\nEnhanced Speed\nHeightened Senses","secondaryAbilities":"Enhanced Awareness\nEnhanced Reflexes\nAcrobatic Movement\nStealth","signatureTechniques":"","transformationDetails":"Venny''Claire''s full werebeast form is a sleek black werepanther with a deep, inky coat that seems to absorb light. Her smaller, compact body is built for speed, stealth, and acrobatic agility. Her only visible dire wolf trait is a silver patch of fur on her right hind leg. She moves with fluid grace and retains her playful curiosity and exceptional awareness."},"is_public":true,"appearance":{"build":["Compact","Lean","Agile"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Deep brown"],"grooming":"Natural","skinTone":["Rich warm brown"],"wardrobe":"Sleeveless linen dress\nLeather sandals","hairColor":["Black"],"hairStyle":"Wild and untamed","accessories":"Braided leather waist cord\nLayered necklaces\nBeaded jewelry\nGold earrings\nGold bracelet","faceDetails":["High cheekbones","Small symmetrical nose","Youthful features"],"hairTexture":["4c","Dense"],"colorPalette":"Warm Brown\nBlack\nNatural Linen\nLeather Brown\nGold\nSilver","dominantHand":"","outfitColors":"Natural linen\nLeather brown\nGold","alternateForm":["Black Werepanther","Sudo Form"],"clothingStyle":"Light, practical clothing that allows unrestricted movement and suits the climate of Moonwood Vail.","appearanceNotes":"Venny''Claire closely mirrors Venny''Macon in facial structure, complexion, eyes, and hair. She is smaller and more compact than her brother, with a lighter frame suited to speed, agility, and acrobatic movement.","outfitMaterials":["Woven linen","Leather","Beads","Metal"],"postureMovement":["Relaxed posture","Fluid movement","Light-footed"],"signatureOutfit":"Simple sleeveless woven linen dress secured with a braided leather waist cord and worn with leather sandals.","distinguishingFeatures":["Large wide-set eyes"]},"created_at":"2026-09-25T17:42:10.890987+00:00","updated_at":"2026-09-25T19:27:29.367547+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"Dire Wolf and Werepanther","storyArc":"","backstory":"","childhood":"","lifestyle":"","